function e(){return(e=t(()=>{i={APP:{about:{description:"Quant a mi",link:"/ca/quant-a-mi",moreInfo:"M\xe9s informaci\xf3"},actions:{click:"Clic",tap:"Toca"},contact:"Contacte",cookies:{accept:"Accepta",message:"Faig servir Google Analytics per comptar les visites a les p\xe0gines. Aix\xf2 implica cookies. Acceptes el seguiment anal\xedtic an\xf2nim? <small><strong>(No es recullen dades personals.)</strong></small>",refuse:"No, gr\xe0cies."},related:"Relacionats",featured:"Treball seleccionat",title:"Luis Kr\xf6tz",preferences:"Prefer\xe8ncies",language:"Idioma",pref:{title:"Prefer\xe8ncies",done:"Fet",appearance:{title:"Aparen\xe7a",desc:"Tria l\u2019aparen\xe7a del lloc",system:{label:"Sistema",sub:"Segueix el sistema"},dark:{label:"Fosc",sub:"Mode fosc"},light:{label:"Clar",sub:"Mode clar"}},motion:{title:"Moviment",desc:"Controla les animacions i transicions",full:{label:"Normal",sub:"Moviment complet"},reduced:{label:"Redu\xeft",sub:"Menys moviment"}},closeLabel:"Tanca les prefer\xe8ncies",devTools:{title:"Eines de desenvolupador",statsForNerds:"Estad\xedstiques per a nerds",statsForNerdsDesc:"HUD en directe de FPS, xarxa i mem\xf2ria, cantonada inferior dreta",showGrid:"Mostra la graella",showGridDesc:"Superposa columnes, espais i \xe0rea m\xe0xima a cada punt de ruptura",reducedMotion:"Moviment redu\xeft",reducedMotionDesc:"Desactiva animacions i transicions"}},carousel:{prev:"Element anterior",next:"Element seg\xfcent",ofLabel:"de"},statsHud:{title:"Rendiment",fps:"FPS",cpu:"CPU",memory:"Mem\xf2ria",network:"Xarxa",latency:"Lat\xe8ncia",requests:"Sol\xb7licituds",gpu:"GPU"},earthPlayground:"Playground de la Terra",starField:"Camp Estel\xb7lar",menu:"Men\xfa",close:"Tanca",skip:"Salta al contingut",loader:{lines:["[SYS_BOOT] INITIALIZING ARCHITECTURE v3.8","[GPU_CORE] ALLOCATING SHADER PIPELINES","[WASM_ENG] THREAD POOL READY: 4 WORKERS","[VRAM_MGR] POOL & PURGE PROTOCOL ENGAGED","[RUNTIME] SYSTEM VERIFIED: LAUNCHING INTERFACE"],initWebGpu:"Inicialitzant WebGPU",title:"Luis Kr\xf6tz",stages:["Resolvent els textos de la interf\xedcie","Carregant fonts i mitjans","Muntant els components","Preparant les p\xe0gines","Interf\xedcie preparada"]},engine:{title:"Motor d'IA",npu:"Maquinari NPU actiu",gpu:"Maquinari GPU actiu",wasm:"Worker WASM actiu",on:"ON",off:"APAGAT",controls:"Estad\xedstiques i controls de rendiment"},media:{preview:"Vista pr\xe8via de contingut multim\xe8dia",videoControls:"Controls de v\xeddeo",autoplay:"Reproducci\xf3 autom\xe0tica de v\xeddeo",goToSlide:"V\xe9s a la diapositiva",toExpand:"per ampliar"},awards:{nextAward:"Temps fins al proper premi",legalNav:"Av\xeds legal"},sitePreferences:"Prefer\xe8ncies del lloc: tema i moviment",loading:"Carregant",notFound:"P\xe0gina no trobada",notify:{title:"Av\xeds",error:"Alguna cosa ha anat malament",loadFailed:"No s'ha pogut carregar una secci\xf3",dismiss:"Descarta la notificaci\xf3"},animations:"Refer\xe8ncia d'Animacions"},components:{contact:{line1:[{description:"Correu",link:"mailto:luis.krotz@gmail.com"},{description:"Tel\xe8fon",link:"tel:+55(51)982-274-782"},{description:"Linkedin",link:"https://www.linkedin.com/in/luis-kr\xf6tz?locale=es_ES"},{description:"Github",link:"https://github.com/LuisKrotz"}],line2:[{description:"Pol\xedtica de privacitat",link:"/ca/politica-de-privacitat"},{description:"GDPR",link:"/ca/rgpd"},{description:"Termes d\u2019\xfas",link:"/ca/termes-d-us"}],title:"Contacte"},"legal-footer":{links:[{link:"/ca",page:"Inici"},{link:"/ca/politica-de-privacitat",page:"Pol\xedtica de privacitat"},{link:"/ca/rgpd",page:"GDPR"},{link:"/ca/termes-d-us",page:"Termes d\u2019\xfas"},{link:"/ca/llicencia",page:"Llic\xe8ncia"}]},media:{close:"Tanca",toOpen:"per obrir",audioNote:"Aquest v\xeddeo presenta \xe0udio en angl\xe8s \u2014 no hi ha traducci\xf3 original disponible."},related:{note:"Tots els mitjans d\u2019aquest domini es van capturar com a captures de pantalla d\u2019URL p\xfabliques i/o entorns de desenvolupament locals usant dades de demostraci\xf3 sense valor de producci\xf3. Tots els drets de propietat intel\xb7lectual pertanyen als respectius propietaris de cada projecte. Aquest portafoli demostra \xfanicament les meves contribucions t\xe8cniques personals com a desenvolupador; la participaci\xf3 d\u2019altres membres de l\u2019equip pot no estar totalment detallada a causa de l\u2019abast del projecte i els registres hist\xf2rics.",path:"/portfolio/",projects:[{featured:!0,link:"metcha",page:"Metcha"},{featured:!1,link:"transa",page:"Transa"},{featured:!0,link:"brazilian-leather",page:"Brazilian Leather"},{featured:!1,link:"mor",page:"Mor"},{featured:!1,link:"coza",page:"Coza"},{featured:!0,link:"melissa",page:"Melissa"},{featured:!1,link:"minimelissa",page:"Minimelissa"},{featured:!1,link:"aboutmarco",page:"Marco Almeida"},{featured:!1,link:"clinica-de-desenvolvimento-nathalia-bond",page:"Nathalia Bond"},{featured:!1,link:"cecerele",page:"Cecerel\xea"},{featured:!1,link:"vibra",page:"Vibra"},{featured:!1,link:"genesysinf-sageweb",page:"Genesysinf"}],title:"Relacionats",socials:[{link:"mailto:luis.krotz@gmail.com",network:"Correu"},{link:"tel:+55(51)982-274-782",network:"Tel\xe8fon"},{link:"https://www.linkedin.com/in/luis-kr%C3%B6tz/?locale=es_ES",network:"Linkedin"},{link:"https://github.com/LuisKrotz",network:"Github"}]},"lang-dialog":{title:"Idioma",close:"Tanca el selector d\u2019idioma"},"source-code":{label:"Project source code:",link:"Git",credit:"Desenvolupament, UI i disseny creatiu, producci\xf3 de contingut, redacci\xf3, traducci\xf3, enginyeria, enginyeria d'UX, revisi\xf3, conceptualitzaci\xf3, producci\xf3, devOps i manteniment d'aquesta plataforma, tot fet per Luis Kr\xf6tz.",rights:"Copyright \xa9 {year} Luis Kr\xf6tz"},"preferences-modal":{title:"Prefer\xe8ncies",close:"Tanca les prefer\xe8ncies"},"docs-portal":{title:"Documentaci\xf3 detallada dels projectes",description:"Disponible nom\xe9s en angl\xe8s",copyToast:"Aquesta p\xe0gina no permet copiar \u2014 consulta github per descarregar el codi font o contacta amb l'administrador de la p\xe0gina."},animations:{"progress-bar":{alt:"Barra de progr\xe9s de ruta que recorre la vora superior durant la navegaci\xf3",longdesc:"La barra fina de progr\xe9s fixada a la vora superior del viewport. Animaci\xf3: un transform scaleX recorre la barra de zero fins aproximadament setanta per cent en uns segons mentre el canvi de ruta \xe9s en curs, despr\xe9s completa fins a cent per cent i s'esvaeix al lloc quan la vista de dest\xed resol \u2014 mai no retrocedeix visiblement. Disparador: arrenca a cada navegaci\xf3 interna i acaba quan la nova vista es munta. Tecnologia: transicions CSS en transform i opacity dirigides per dues classes d'estat \u2014 zero JavaScript per frame. Prop\xf2sit: comunicar que una transici\xf3 de p\xe0gina \xe9s en curs, a l'estil nprogress."},"burger-button":{alt:"Bot\xf3 del men\xfa hamburguesa amb animaci\xf3 de morph l\xedquid",longdesc:"El bot\xf3 del men\xfa hamburguesa a la cantonada superior dreta de cada p\xe0gina. Animaci\xf3: morph l\xedquid entre la icona de tres l\xednies i la X de tancament \u2014 els tra\xe7os es corben i es fonen com a fluid en lloc de girar r\xedgidament. Disparador: es reprodueix en fer clic/tocar quan el men\xfa obre i es reverteix quan tanca; el hover canvia la tensi\xf3 dels tra\xe7os. Tecnologia: widget canvas dirigit per Rust/WASM (shader de fragment WebGL), amb variant en worker WebGPU/OffscreenCanvas i fallback CSS pur. Prop\xf2sit: comunicar l'estat obert/tancat del men\xfa amb una transici\xf3 t\xe0ctil i f\xedsica."},"nav-menu-background":{alt:"Fons animat a pantalla completa del men\xfa amb camp de contorns fluid",longdesc:"El fons a pantalla completa pintat darrere de l'overlay del men\xfa de navegaci\xf3. Animaci\xf3: un camp de contorns fractals en moviment lent \u2014 capes de soroll fbm deriven i es remodelen cont\xednuament, com un miratge de calor o plasma. Disparador: arrenca quan el men\xfa hamburguesa obre, s'atura i es descarta quan tanca. Tecnologia: shader de fragment WebGL (fbm en GLSL) en un canvas dedicat, amb variant WebGPU/OffscreenCanvas en worker i fallback de degradat CSS est\xe0tic. Prop\xf2sit: donar al men\xfa una profunditat atmosf\xe8rica viva en lloc d'un panell de color pla."},"nav-menu":{alt:"\xcdtems del men\xfa de navegaci\xf3 amb entrada ascendent esglaonada",longdesc:"L'overlay del men\xfa de navegaci\xf3 que obre pel bot\xf3 hamburguesa. Animaci\xf3: cada \xedtem entra amb pujada i fade esglaonats (nav-menu-item-in), lliscant uns p\xedxels cap amunt mentre apareix; un reflex de membrana/plasma deriva pel panell en loop lent. Disparador: l'entrada es reprodueix una vegada per obertura, seq\xfcenciada de dalt a baix; la deriva de la membrana fa loop mentre el men\xfa est\xe0 obert. Tecnologia: keyframes CSS amb delays per \xedtem, zero JavaScript per frame. Prop\xf2sit: seq\xfcenciar els enlla\xe7os perqu\xe8 l'ull els llegeixi en ordre en lloc d'un flash \xfanic."},"nav-flag":{alt:"Icona de bandera de l'idioma amb animaci\xf3 d'ona i entrada",longdesc:"El petit canvas de bandera al costat de l'etiqueta d'idioma a la barra de navegaci\xf3. Animaci\xf3: la tela de la bandera ondula amb un ripple sinusoidal i el glif sencer entra amb escala (nav-flag-in) quan la nav munta o l'idioma canvia. Tecnologia: widget canvas que renderitza la bandera proceduralment (les banderes de pa\xefsos dividits es componen), amb el keyframe CSS encarregat de l'entrada. Prop\xf2sit: marcar l'idioma actiu amb una bandera que sembla tela, no una icona plana."},"switch-slider":{alt:"Interruptor de prefer\xe8ncia amb lliscament l\xedquid del polze",longdesc:"Els interruptors d'ences/apagat dins el di\xe0leg de prefer\xe8ncies (aparen\xe7a, moviment, efectes). Animaci\xf3: el polze es llisca pel rail amb estirament l\xedquid \u2014 s'allarga durant el trajecte i torna al rep\xf2s, com una gota. Disparador: es reprodueix en fer clic/tocar o alternar per teclat. Tecnologia: widget WebGL/canvas (dirigit per Rust/WASM) pintant rail i polze, amb fallback CSS per motors sense WebGL. Prop\xf2sit: donar tacte a l'estat binari i confirmar que l'alternan\xe7a ha passat."},"theme-slider":{alt:"Alternador de tema amb lliscament orbital dia/nit",longdesc:"L'interruptor de tema clar/fosc al di\xe0leg de prefer\xe8ncies i la navegaci\xf3. Animaci\xf3: el polze viatja com un cos orbital \u2014 un disc dia/nit travessa el rail mentre glifs de sol/lluna fan crossfade dins seu. Disparador: es reprodueix en alternar; tamb\xe9 una vegada en carregar quan el tema desat difereix del predeterminat. Tecnologia: widget WebGL/canvas (dirigit per Rust/WASM) amb fallback CSS. Prop\xf2sit: narrar el canvi de tema com una albada/capvespre en lloc d'un flip binari."},"close-button":{alt:"Bot\xf3 de tancar amb ompliment l\xedquid i X girat\xf2ria",longdesc:"El bot\xf3 circular de tancar dels modals i del lightbox de mitjans expandit. Animaci\xf3: en hover un ompliment l\xedquid puja dins el cercle mentre els tra\xe7os de la X giren i es tensen; en pr\xe9mer, l'ompliment s'encalla. Disparador: hover/focus l'arma, pr\xe9mer l'allibera. Tecnologia: widget WebGL/canvas (dirigit per Rust/WASM) amb un bot\xf3 CSS senzill a sota per motors sense WebGL. Prop\xf2sit: donar al tancament una sensaci\xf3 f\xedsica i satisfact\xf2ria de pressi\xf3."},skeleton:{alt:"Esquelet de c\xe0rrega amb cel\xb7les en morph i brillantor",longdesc:"Els esquelets de placeholder mostrats on el contingut encara carrega (figures de mitjans, blocs de text, tiles de projecte). Animaci\xf3: cel\xb7les de glif fan morph entre formes 0/1 mentre una brillantor en degradat travessa la superf\xedcie d'esquerra a dreta (skeleton-shimmer). Disparador: corre cont\xednuament mentre el contingut carrega, despr\xe9s lliura a l'element real. Tecnologia: widget canvas (morph de cel\xb7les dirigit per Rust/WASM) m\xe9s el keyframe CSS del shimmer. Prop\xf2sit: senyalar \"el contingut arriba\" amb moviment que anticipa el layout en lloc d'un spinner."},"intro-loader":{alt:"Loader d'introducci\xf3 amb anells contrarrotatius i progr\xe9s",longdesc:"El loader d'arrencada a pantalla completa mostrat mentre carreguen els primers assets del lloc. Animaci\xf3: dos anells giren en direccions oposades (intro-loader-spin-cw/ccw) al voltant d'un comptador de percentatge i missatges d'etapa localitzats. Disparador: corre des de la c\xe0rrega de la p\xe0gina fins que el bundle d'arrencada est\xe0 llest, quan el loader sencer s'esvaeix i es retira. Tecnologia: keyframes CSS girant els anells; el JS nom\xe9s reporta progr\xe9s. Prop\xf2sit: mantenir el primer paint viu i llegible durant la seq\xfc\xe8ncia d'arrencada de tiers/polyfills."},"site-toast":{alt:"Toast de notificaci\xf3 lliscant des de la cantonada",longdesc:"El petit toast de notificaci\xf3 que apareix en una cantonada de la pantalla per esdeveniments com confirmacions de c\xf2pia i accions de cookies. Animaci\xf3: es llisca des de la vora mentre puja amb fade (site-toast-in), aguanta i surt lliscant-se de tornada amb fade. Disparador: disparat per esdeveniments de l'app (c\xf2pia, av\xeds d'emmagatzematge, notificaci\xf3 de prova). Tecnologia: keyframes CSS a l'entrada i un modificador --closing a la sortida. Prop\xf2sit: atreure la vista a un missatge transitori sense blocar la interacci\xf3."},"mosaic-burn":{alt:"T\xedtol del tile de portafoli cremant-se en brases i rearmant-se",longdesc:"El text del t\xedtol als tiles del mosaic de treballs destacats. Animaci\xf3: en hover les lletres del t\xedtol entren en combusti\xf3 \u2014 vores erosionades, estelades de cremada i part\xedcules de brasa incandescent consumeixen els glifs columna per columna, i les lletres es reconstrueixen de baix a dalt pel mateix camp de foc quan el punter surt o el hover canvia d'objectiu. Disparador: hover del punter al tile. Tecnologia: simulaci\xf3 de part\xedcules en Rust/WASM (crate mosaic-burn) corrent el model erode/scorch/ember en un canvas; un cam\xed 2D-canvas renderitza el mateix camp quan la ruta GPU est\xe0 apagada \u2014 tots dos comparteixen una simulaci\xf3 determin\xedstica. Prop\xf2sit: convertir el hover simple en l'efecte de foc ins\xedgnia del lloc."},"mosaic-tile":{alt:"Tile de portafoli lliscant a nou slot amb ressort + brillantor a la vora",longdesc:"Les targetes de projecte al mosaic de treballs destacats. Animaci\xf3: quan una targeta s'expandeix en hover, els veins despla\xe7ats es llisquen als seus nous slots amb un ressort amortit \u2014 una corba org\xe0nica d'overshoot i assentament (ressort sintetitzat en CSS linear()) en lloc d'un lliscament lineal; una brillantor recorre peri\xf2dicament la vora de cada tile. Disparador: el repack per hover anima els tiles despla\xe7ats; la brillantor de la vora fa loop suaument. Tecnologia: pack masonry en JS + transici\xf3 CSS en transform; la brillantor \xe9s una passada d'anell en canvas. Prop\xf2sit: mantenir la paret l\xedquida i viva mentre es reordena."},"media-progressive":{alt:"Imatge de mitjans passant de borrosa en baixa qualitat a n\xedtida en alta",longdesc:"Cada figura de mitjans del lloc (imatges i v\xeddeos dels projectes). Animaci\xf3: un placeholder de baixa resoluci\xf3 pinta primer, despr\xe9s fa morph a l'asset d'alta resoluci\xf3 decodificat \u2014 la capa d'alta es resol des de l'estat borr\xf3s/ampliat del thumb en lloc de pampalluguejar, aix\xed l'ull llegeix una nitidesa cont\xednua. Disparador: arrenca quan la figura entra a la viewport (IntersectionObserver) i l'asset acaba el decode al pool WASM. Tecnologia: decode d'imatge WASM fora del fil principal, canvi a blob-URL i morph en CSS/canvas. Prop\xf2sit: fer que la c\xe0rrega progressiva sembli la imatge entrant a focus, no una substituci\xf3 dura."},"glitch-portrait":{alt:"Retrat de l'About amb animaci\xf3 de corrupci\xf3 glitch VHS",longdesc:"La imatge del retrat a la secci\xf3 About. Animaci\xf3: corrupci\xf3 peri\xf2dica estil VHS \u2014 rotllos de scanline, separaci\xf3 de canals, despla\xe7ament de blocs i bandes de soroll escombren la foto breument abans que torni neta. Disparador: corre en un timer aleatori mentre la secci\xf3 est\xe0 en pantalla. Tecnologia: passada de shader de fragment WebGL en la textura del retrat amb fallback canvas. Prop\xf2sit: donar al retrat una personalitat viva de v\xeddeo anal\xf2gic, d'acord amb l'est\xe8tica t\xe8cnica del lloc."},"divider-sheen":{alt:"Divisor del peu amb una brillantor de llum viatgera",longdesc:"Els divisors hairline que separen seccions de p\xe0gina i columnes del peu. Animaci\xf3: una banda suau de llum viatja lentament pel fil, escombrant de punta a punta en loop continu. Disparador: corre cont\xednuament mentre el divisor est\xe0 en pantalla. Tecnologia: widget canvas pintant la l\xednia m\xe9s la banda de degradat en moviment. Prop\xf2sit: elevar una regla est\xe0tica a un detall subtil i viu."},"text-draw":{alt:"Text dibuixant-se lletra a lletra com a manuscrit",longdesc:"T\xedtols de secci\xf3, enlla\xe7os i llegendes amb el tractament draw-text a tot el lloc. Animaci\xf3: cada car\xe0cter es dibuixa estil tra\xe7 de ploma en ordre de lectura \u2014 els tra\xe7os s'escriuen seq\xfcencialment com cal\xb7ligrafia o plotter, amb agrupaci\xf3 opcional per paraula. Disparador: es reprodueix quan l'element entra a la viewport (IntersectionObserver, disparador viewport) o per dispatch expl\xedcit. Tecnologia: dibuix instanciat per car\xe0cter en canvas (widget text-draw en Rust/WASM) amb fallback en keyframe CSS (char-draw/word-draw). Prop\xf2sit: fer que els t\xedtols semblin autografiats \u2014 escrits davant teu en lloc d'estampats."},"ring-sheen":{alt:"Vora de tile amb brillantor viatjant per l'anell",longdesc:"Els contorns de vora als tiles del mosaic i de projectes relacionats. Animaci\xf3: una banda de brillantor viatja per l'anell de la vora del tile com llum lliscant en un marc, en loop peri\xf2dic lent. Disparador: fa loop mentre el tile est\xe0 visible; s'intensifica en hover. Tecnologia: passada d'anell en canvas composta sobre la vora del tile. Prop\xf2sit: mantenir vives les graelles de targetes est\xe0tiques amb un reflex ambiental barat."},"corner-brackets":{alt:"Cantonades de bot\xf3 expandint-se en claud\xe0tors en hover",longdesc:"Les decoracions de claud\xe0tors de cantonada als botons d'acci\xf3 (barres de tancar, CTAs). Animaci\xf3: els quatre claud\xe0tors de cantonada s'expandeixen cap enfora i s'aclareixen en hover, despr\xe9s es contreuen de tornada \u2014 com un reticle d'enfocament de c\xe0mera encallant-se. Disparador: hover/focus al bot\xf3. Tecnologia: petit widget canvas per bot\xf3 (dibuix instanciat de claud\xe0tors) amb fallback en transici\xf3 CSS. Prop\xf2sit: comunicar interactivitat amb una pista d'enfocament precisa i instrumental."},"scene-3d":{alt:"Escena 3D interactiva de camp estel\xb7lar i terra",longdesc:"Les escenes 3D a pantalla completa \u2014 l'experiment star-field (cossos celestes en \xf2rbita amb etiquetes de dossier) i el playground de la terra (planeta girant amb controls d'\xf2rbita). Animaci\xf3: moviment continu inspirat en f\xedsica \u2014 mec\xe0nica orbital, rotaci\xf3, paral\xb7laxi al moviment de c\xe0mera i transicions entre cossos. Disparador: corre tot el temps que l'escena est\xe0 en pantalla; punter/tou orbita la c\xe0mera. Tecnologia: three.js sobre WebGL/WebGPU amb el treball per frame a la GPU. Prop\xf2sit: la vitrina 3D en temps real ins\xedgnia del lloc."},"genie-modal":{alt:"Mitj\xe0 expandit obrint-se en warp l\xedquid cap al lightbox",longdesc:"El lightbox de mitjans expandits que obre en fer clic en una imatge o v\xeddeo de projecte. Animaci\xf3: el mitj\xe0 es deforma entre el rectangle de la figura clicada i la caixa del modal a pantalla completa com una l\xe0mina l\xedquida \u2014 bandes horitzontals s'endarrereixen, es corben i s'estiren per un camp genie mentre part\xedcules de vapor es desprenen del plec en moviment; el mateix camp el col\xb7lapsa de tornada en tancar. Disparador: clic/tocar per obrir, bot\xf3 de tancar o Escape per col\xb7lapsar. Tecnologia: widget WebGPU/Rust de mesh-warp + part\xedcules en un worker fora del fil principal quan est\xe0 habilitat, un renderer 2D-canvas de bandes sense al\xb7locaci\xf3 per frame a tota la resta, i un keyframe CSS de zoom com a \xfaltim recurs. Prop\xf2sit: substituir un scale-fade dur per una transici\xf3 f\xedsica estil dock de macOS."},carousel:{alt:"Carrusel de premis lliscant amb momentum i barra de progr\xe9s",longdesc:"El carrusel horitzontal de premis al peu de la home. Animaci\xf3: els \xedtems es llisquen amb momentum i fan snap a la posici\xf3; una barra de progr\xe9s s'omple al llarg del rail, un tra\xe7 d'autoplay anima el temporitzador i els controls d'acci\xf3 apareixen. Disparador: gestos d'arrossegament/scroll, controls anterior/seg\xfcent i el timer d'autoplay. Tecnologia: scroll snapping nadiu m\xe9s springs en JS i keyframes CSS per al chrome. Prop\xf2sit: fer que fullejar la tira de premis sembli barrejar cartes f\xedsiques."},"about-text":{alt:"Par\xe0graf de l'About revelant els seus car\xe0cters u a u",longdesc:"Els par\xe0grafs de biografia a la secci\xf3 About. Animaci\xf3: el text es revela car\xe0cter a car\xe0cter en l'ordre de les frases \u2014 cada lletra s'esvaeix/es mou en el seu propi temps, aix\xed el par\xe0graf sembla escriure's sol. Disparador: es reprodueix quan la secci\xf3 entra a la viewport. Tecnologia: JS seq\xfc\xe8ncia spans per car\xe0cter amb timing dirigit per rAF; el CSS cuida de la transici\xf3 per car\xe0cter. Prop\xf2sit: donar a la bio una cad\xe8ncia de m\xe0quina d'escriure/veu d'acord amb els t\xedtols draw-text."},"related-tile":{alt:"Targeta de projecte relacionat elevant-se i fent zoom en hover",longdesc:"Les targetes de projectes relacionats al final de les p\xe0gines de projecte. Animaci\xf3: en hover la targeta s'eleva, la imatge fa un zoom suaument i t\xedtol/descripci\xf3 pugen \u2014 tot amb easing de ressort amortit (springs sintetitzats en CSS linear()) perqu\xe8 el moviment passi lleugerament i s'assenti de forma org\xe0nica; una brillantor escombra la vora de la targeta. Disparador: hover/focus del punter. Tecnologia: transicions CSS en transform/opacity dirigides per corbes de ressort. Prop\xf2sit: fer que l'affordance de navegaci\xf3 se senti f\xedsica i convidant."},"note-dot":{alt:"Marcador de nota pulsant suaument",longdesc:"Els petits marcadors de nota/punt usats a les p\xe0gines d'internals (documentaci\xf3 i internes de projecte). Animaci\xf3: el punt pulsa suaument \u2014 un loop respirant d'escala i fade. Disparador: fa loop cont\xednuament en pantalla. Tecnologia: un keyframe CSS (note-dot-pulse). Prop\xf2sit: marcar l'element com a anotaci\xf3 viva sense exigir atenci\xf3."},"body-glow":{alt:"Brillantor ambient de la p\xe0gina derivant darrere el contingut",longdesc:"La brillantor de fons ambient darrere el contingut de la p\xe0gina. Animaci\xf3: un gran degradat radial suau deriva lentament pel document, canviant posici\xf3 i intensitat en un loop llarg. Disparador: corre cont\xednuament a totes les p\xe0gines. Tecnologia: un keyframe CSS (body-glow-drift) animant una capa de fons fixa \u2014 zero JavaScript. Prop\xf2sit: donar atmosfera i profunditat al tema fosc en lloc d'un fons pla."}}},pages:{HOME:{archive:"Explora m\xe9s",explore:"Mira",featured:"Treball seleccionat",message:"Treball seleccionat",portfoliolist:[{description:"Construcci\xf3 i escalat del Dell Design System per donar servei a m\xe9s de 500 productes empresarials.<br>Actuant com a Enginyer de Software, Agile Champion, Tech Lead i Analista de Suport en fluxos de treball interfuncionals d'enginyeria, accessibilitat, contingut, disseny i especificacions d'IA per assolir la creaci\xf3 fluida de components multiframework, paritat, suport i manteniment a trav\xe9s de Vanilla, React, Angular i Visualitzaci\xf3 de Dades per a un disseny i experi\xe8ncies d'usuari unificades.",height:["769","793"],image:"dell-design-system",label:"Dell Design System",link:"dell-design-system",width:["1230","889"],featured:!0},{description:"Un oracle de cuir, disseny i cultura.<br>Desenvolupada a Transa Inc. en col\xb7laboraci\xf3 amb Leather Naturally, la plataforma explica hist\xf2ries captivadores dels m\xf3ns del disseny, l\u2019art, la moda i el lifestyle, destacant les persones que donen forma a la cultura creativa.",height:["750","301"],image:"metcha",label:"Metcha",link:"metcha",width:["1915","768"],featured:!0},{description:"Un portal de marca que connecta tot el relacionat amb Melissa.<br>Inclo\xefa feeds de xarxes socials i contingut original creat a Transa Inc.",height:["799","320"],image:"melissa",label:"Melissa",link:"melissa",width:["1920","768"],featured:!0},{description:"Un projecte desenvolupat a Transa Inc. per al Grup Grendene com a canal dedicat a la marca Mini Melissa.<br>El lloc presentava un feed de contingut i un feed social amb scroll infinit, oferint contingut exclusiu de Mini Melissa. Actiu del 2018 al 2020.",height:["799","322"],image:"minimelissa-cropped",label:"Mini melissa",link:"mini-melissa",width:["1905","768"],featured:!1},{description:"Un projecte desenvolupat a Transa Inc. mitjan\xe7ant una alian\xe7a entre CICB i Apex-Brasil.<br>Un portal per al cuir brasiler, que reuneix llocs com Brazilian Leather, CICB, CSCB i Leather Law.",height:["850","340"],image:"brazilian-leather",label:"Brazilian leather",link:"cicb",width:["1920","768"],featured:!0},{description:"Un projecte desenvolupat a Transa Inc. amb l\u2019objectiu de crear una experi\xe8ncia r\xe0pida i bonica que connect\xe9s els canals i la comunitat de MOR en un sol lloc.",height:["798","319"],image:"mor",label:"Mor",link:"mor",width:["1920","768"],featured:!1},{description:"Un projecte desenvolupat a Transa Inc. del 2017 al 2019.<br>La p\xe0gina principal de Coza era un feed de contingut de la marca, amb articles, galeries, fotos i enlla\xe7os a la botiga en l\xednia.",height:["794","318"],image:"coza",label:"Coza",link:"coza",width:["1920","768"],featured:!1},{description:"El portafoli de Marco, desenvolupat com a projecte freelance el 2021.<br>L\u2019objectiu principal era lliurar una UI pixel-perfect amb animacions flu\xefdes i un enfocament centrat en el rendiment.",height:["1014","406"],image:"aboutmarco",label:"Marco almeida",link:"aboutmarco",width:["1920","768"],featured:!1},{description:"Un lloc web desenvolupat com a projecte freelance el 2021.<br>El lloc de Nathalia Bond va ser un redisseny de l\u2019anterior, mantenint la identitat visual ja establerta, amb focus en refinar-la, i usant Squarespace com a sistema de gesti\xf3 de continguts f\xe0cil de mantenir per a l\u2019usuari final.",height:["640","320"],image:"clinica-nathalia-bond-v3",label:"Nathalia bond",link:"nathalia-bond",width:["1920","960"],featured:!1},{description:"Un lloc d\u2019e-commerce desenvolupat com a projecte freelance el 2021.<br>La botiga de Cecerel\xea va ser dissenyada per mi a la plataforma d\u2019e-commerce Illuria.",height:["640","256"],image:"cecerele",label:"Cecerel\xea",link:"cecerele",width:["1920","768"],featured:!1},{description:"Un lloc web desenvolupat a i per a Transa Inc., compost per un feed amb scroll infinit, un CMS propi i p\xe0gines 'join us' i 'cases' que resumeixen projectes desenvolupats durant molts anys.",height:["850","369"],image:"transa",label:"Transa",link:"transa",width:["1920","768"],featured:!1},{description:"Un lloc web desenvolupat a Transa Inc. el 2016 com a portal creat per a la marca Vibra.",height:["913","340"],image:"vibra",label:"Vibra",link:"vibra",width:["1920","768"],featured:!1},{description:"Un projecte desenvolupat per Genesysinf a Santana do Livramento, Brasil: programari fiscal.<br>El projecte consistia a portar el codi del programari d\u2019escriptori Sage a una nova versi\xf3 web.",height:["649","369"],image:"sageweb",label:"Sageweb",link:"sage",width:["1350","768"],featured:!1}]},about:{col1:['Hola, s\xf3c en Luis,<br />un enginyer de programari centrat en UX.<br>Actualment treballo a Dell en el <a href="https://www.delldesignsystem.com" target="_blank">Dell Design System</a>.',"S\xf3c un professional de TI amb amplia experi\xe8ncia en desenvolupament web, an\xe0lisi de sistemes i gesti\xf3 de projectes. M\u2019especialitzo en la construcci\xf3 de solucions digitals innovadores i eficients, amb un fort focus en SEO, accessibilitat i rendiment. La meva traject\xf2ria en programaci\xf3 abasta ASP, PHP, C, C#, Pascal, Delphi, JavaScript i SQL, a m\xe9s de frameworks moderns com React, Vue i Angular."],col2:["Vaig estudiar a la UFSM (Universitat Federal de Santa Maria) a Frederico Westphalen, Brasil, on vaig obtenir el t\xedtol en Tecnologia de Sistemes per a Internet, seguit d\u2019un postgrau en <span lang=\"pt-br\">'Gest\xe3o de T.I'</span> (Gesti\xf3 de TI) a la UFSM.","El meu treball sempre se centra a lliurar layouts pixel-perfect: codi f\xe0cil d\u2019usar, r\xe0pid, bonic i flu\xeft.","M\u2019encanten les animacions en CSS. Vaig passar anys creant les col\xb7leccions de temporada de Melissa gaireb\xe9 \xedntegrament en CSS i, des de llavors, he treballat amb animacions basades en JS usant Vue i Lottie, he experimentat amb Three.js i recentment he comen\xe7at a explorar el desenvolupament guiado per especificacions i la IA."],frame:'Hola, s\xf3c en Luis,<br />un enginyer de programari centrat en UX.<br>Actualment treballo a Dell en el <a href="https://www.delldesignsystem.com" target="_blank">Dell Design System</a>.',mentions:"Algunes mencions:",mention_items:[{description:"Ago. 2013:<br>A la UFSM, entre els 40 millors treballs del 28\xe8 JAI",icon:"\ud83c\udfc6",link:"http://coral.ufsm.br/prpgp/images/fomularios-diversos/2013/40-MELHORES-JAI-2013.pdf"},{description:"14 de juny de 2020:<br>Premi CSSDA Special Kudos, atorgat a la primera versi\xf3 de luiskr.com",link:"https://www.cssdesignawards.com/sites/luiskr/37252",media:{height:"1123",path:"awards/cssda-special-kudos-1.svg",width:"794"}},{description:"14 de juny de 2020:<br>Premi CSSDA Innovation Design, atorgat a la primera versi\xf3 de luiskr.com",link:"https://www.cssdesignawards.com/sites/luiskr/37252",media:{height:"1273",path:"awards/cssda-inn-Luiskr-1.svg",width:"993"}},{description:"14 de juny de 2020:<br>Premi CSSDA UX Design, atorgat a la primera versi\xf3 de luiskr.com",link:"https://www.cssdesignawards.com/sites/luiskr/37252",media:{height:"1132",path:"awards/cssda-ux-Luiskr-1.svg",width:"893"}},{description:"14 de juny de 2020:<br>Premi CSSDA UI Design, atorgat a la primera versi\xf3 de luiskr.com",link:"https://www.cssdesignawards.com/sites/luiskr/37252",media:{height:"1123",path:"awards/cssda-ui-Luiskr-1.svg",width:"886"}},{description:"6 d\u2019oct. de 2021:<br>Destacat a TCG",icon:"\ud83c\udf10",link:"https://www.topcssgallery.com/gallery/luis-krotz/"},{description:"6 d\u2019oct. de 2021:<br>CSSW Star",link:"https://www.csswinner.com/details/luis-krtz/15699",media:{height:"1132",path:"awards/CSSW-15699-Star-Certificate.svg",width:"993"}},{description:"13 d\u2019oct. de 2021:<br>Destacat a Mindsparkle Mag",icon:"\ud83c\udf10",link:"https://mindsparklemag.com/website/luis-krotz"},{description:"19 de mar\xe7 de 2024:<br>Treball publicat: 'Desenvolvimento de um prot\xf3tipo para gest\xe3o de conhecimento utilizando Lunr.js'",icon:"\ud83d\udcd8",link:"https://repositorio.ufsm.br/handle/1/32752"}],title:"Quant a mi",profilePicture:"https://gravatar.com/avatar/6eff24eea3fb805dfa84837e62ae72ab242378ac3b35bd0e763168f6efe15746?v=1786948200000&size=1280"},GDPR:{title:"GDPR",sections:[{title:"Drets de protecci\xf3 de dades",content:["Vull assegurar-me que coneixes plenament els teus drets de protecci\xf3 de dades. Tot usuari t\xe9 dret al seg\xfcent:","<strong>El dret d\u2019acc\xe9s</strong>: Pots sol\xb7licitar c\xf2pies de les teves dades. No emmagatzemo dades personals; amb gust comparteixo les dades de Google Analytics si cal.","<strong>El dret de rectificaci\xf3</strong>: Tens dret a sol\xb7licitar la correcci\xf3 de qualsevol informaci\xf3 que consideris inexacta, o a completar informaci\xf3 incompleta.","<strong>El dret de supressi\xf3</strong>: Tens dret a sol\xb7licitar que esborri les teves dades personals, sota certes condicions.","<strong>El dret a restringir el tractament</strong>: Tens dret a sol\xb7licitar que restringeixi el tractament de les teves dades personals, sota certes condicions.","<strong>El dret d\u2019oposici\xf3 al tractament</strong>: Tens dret a oposar-te al tractament de les teves dades personals, sota certes condicions.","<strong>El dret a la portabilitat de les dades</strong>: Tens dret a sol\xb7licitar que transferisci les dades recollides a una altra organitzaci\xf3, o directament a tu, sota certes condicions.",'Si fas una sol\xb7licitud, tinc un mes per respondre\u2019t. Si vols exercir algun d\u2019aquests drets, contacta\u2019m per correu electr\xf2nic: <a href="mailto:luis.krotz@gmail.com">luis.krotz@gmail.com</a>.']}]},"privacy-policy":{sections:[{content:["A <a target='_blank' href='/'><span >luiskr</span></a>, accessible des de <a target='_blank' href='/'>https://luiskr.com</a>, una de les meves principals prioritats \xe9s la privacitat dels meus visitants. Aquest document de Pol\xedtica de privacitat cont\xe9 els tipus d\u2019informaci\xf3 que <a target='_blank' href='/'><span >luiskr.com</span></a> recull i registra, i com la faig servir.","Si tens preguntes addicionals o necessites m\xe9s informaci\xf3 sobre la meva Pol\xedtica de privacitat, no dubtis a contactar-me.","Aquesta Pol\xedtica de privacitat s\u2019aplica nom\xe9s a les meves activitats en l\xednia i \xe9s v\xe0lida per als visitants del meu lloc web pel que fa a la informaci\xf3 que van compartir i/o recollir a <a target='_blank' href='/'><span >luiskr.com</span></a>. Aquesta pol\xedtica no s\u2019aplica a informaci\xf3 recollida fora de l\xednia ni per canals diferents d\u2019aquest lloc web."],title:"El de sempre"},{content:["En usar el meu lloc web, consents la meva Pol\xedtica de privacitat i acceptes els seus termes."],title:"Consentiment"},{content:["La informaci\xf3 personal que se\u2019t demana i les raons per les quals es demana t\u2019esclareixeran en el moment en qu\xe8 et demani les dades personals.","Si em contactes directament, puc rebre informaci\xf3 addicional sobre tu, com el teu nom, correu electr\xf2nic, tel\xe8fon, el contingut del missatge i/o adjunts que envi\xefs, i qualsevol altra informaci\xf3 que decideixis proporcionar."],title:"Informaci\xf3 que recullo"},{content:["Faig servir la informaci\xf3 recollida de diverses maneres, incloent-hi per:<ol><li>Proveir, operar i mantenir el meu lloc web</li><li>Millorar, personalitzar i ampliar el meu lloc web</li><li>Entendre i analitzar com uses el meu lloc web</li><li>Desenvolupar nous productes, serveis, funcions i funcionalitats</li><li>Trobar i prevenir fraus</li><li>Fitxers de registre</li></ol>","<a target='_blank' href='/'><span >luiskr.com</span></a> segueix un procediment est\xe0ndard d\u2019\xfas de fitxers de registre. Aquests fitxers registren els visitants quan accedeixen a llocs web. Totes les empreses d\u2019allotjament ho fan com a part de l\u2019anal\xedtica dels serveis d\u2019allotjament. La informaci\xf3 recollida pels fitxers de registre inclou adreces de protocol d\u2019internet (IP), tipus de navegador, prove\xefdor de serveis d\u2019internet (ISP), data i hora, p\xe0gines d\u2019origen/sortida i, possiblement, el nombre de clics. Aquestes dades no estan vinculades a informaci\xf3 personalment identificable. La informaci\xf3 s\u2019usa per analitzar tend\xe8ncies, administrar el lloc, seguir la navegaci\xf3 dels usuaris i recopilar dades demogr\xe0fiques. La meva Pol\xedtica de privacitat va ser creada amb l\u2019ajuda del Privacy Policy Generator i del Disclaimer Generator."],title:"Com faig servir la teva informaci\xf3"},{content:["La Pol\xedtica de privacitat de <a target='_blank' href='/'><span >luiskr.com</span></a> no s\u2019aplica a altres anunciants o llocs web. Per aix\xf2, t\u2019aconsello consultar les respectives pol\xedtiques de privacitat d\u2019aquests servidors d\u2019anuncis de tercers per a informaci\xf3 m\xe9s detallada. Poden incloure les seves pr\xe0ctiques i instruccions sobre com desactivar certes opcions.","Pots desactivar les cookies a les opcions del teu navegador. Per a informaci\xf3 m\xe9s detallada sobre la gesti\xf3 de cookies en navegadors espec\xedfics, consulta els llocs web dels respectius navegadors."],title:"Pol\xedtiques de privacitat de tercers"},{content:["Segons la CCPA, entre altres drets, els consumidors de Calif\xf2rnia tenen dret a:","Sol\xb7licitar que una empresa que recull dades personals de consumidors reveli les categories i les dades personals espec\xedfiques recollides sobre ells.","Sol\xb7licitar que una empresa elimini qualsevol dada personal del consumidor que hagi recollit.","Sol\xb7licitar que una empresa que ven dades personals de consumidors no vengui les dades personals del consumidor.","Si fas una sol\xb7licitud, tinc un mes per respondre\u2019t. Si vols exercir algun d\u2019aquests drets, contacta\u2019m."],title:"Drets de privacitat CCPA (no vendre les meves dades personals)"},{content:["Una altra de les meves prioritats \xe9s afegir protecci\xf3 per als infants mentre usen internet. Animo pares i tutors a observar, participar i/o monitoritzar i guiar la seva activitat en l\xednia.","<a target='_blank' href='/'><span >luiskr.com</span></a> no recull a consci\xe8ncia informaci\xf3 personal identificable de menors de 13 anys. Si creus que el teu fill va proporcionar aquest tipus d\u2019informaci\xf3 al meu lloc web, t\u2019encoratjo a contactar-me <strong>immediatament</strong> i far\xe9 el possible per localitzar aquesta informaci\xf3 amb promptitud."],title:"Informaci\xf3 de menors"}],title:"Pol\xedtica de privacitat"},"terms-of-use":{sections:[{content:["El lloc web luiskr.com situat a <a target='_blank' href='/'>luiskr.com</a> est\xe0 sota LLIC\xc8NCIA MIT. <a target='_blank' href='/'>Luiskr.com</a> est\xe0 creat per Luis Kr\xf6tz; certes funcions del Lloc poden estar subjectes a directrius, termes o regles addicionals, que es publicaran al Lloc en relaci\xf3 amb aquestes funcions.","Tots aquests termes, directrius i regles addicionals queden incorporats per refer\xe8ncia a aquests Termes.","Aquests Termes d\u2019\xfas descriuen els termes i condicions legalment vinculants que regeixen el teu \xfas del Lloc. EN ACCEDIR AL LLOC, ACCEPTES QUEDAR VINCULAT A AQUESTS TERMES i declares que tens l\u2019autoritat i la capacitat per subscriure\u2019ls. HAS DE TENIR COM A M\xcdNIM 18 ANYS PER ACCEDIR AL LLOC. SI NO EST\xc0S D\u2019ACORD AMB TOTES LES DISPOSICIONS D\u2019AQUESTS TERMES, NO ACCEDEIXIS NI USIS EL LLOC WEB.","Aquests termes requereixen l\u2019\xfas d\u2019arbitratge segons la Secci\xf3 10.2 sobre base individual per resoldre disputs, i tamb\xe9 limiten els recursos disponibles per a tu en cas de disputa."],title:"Versi\xf3 1.1"},{content:["<strong>Subjecte a aquests Termes.</strong> <strong><a target='_blank' href='/'>luiskr.com</a></strong> et concedeix una llic\xe8ncia intransferible, no exclusiva, revocable i limitada per accedir al Lloc \xfanicament per al teu \xfas personal i no comercial.","<strong>Certaines restriccions.</strong> Els drets que se\u2019t concedeixen en aquests Termes estan subjectes a les restriccions seg\xfcents: (a) no pots vendre, llogar, cedir, transferir, assignar, distribuir, allotjar ni explotar comercialment el Lloc; (b) no pots modificar, crear obres derivades, desmuntar, compilar inversament ni fer enginyeria inversa de cap part del Lloc; (c) no pots accedir al Lloc per construir un lloc web similar o competidor; i (d) llevat que s\u2019indiqui expressament, cap part del Lloc es pot copiar, reproduir, distribuir, republicar, descarregar, mostrar, publicar o transmetre en cap forma ni per cap mitj\xe0; qualsevol futura versi\xf3, actualitzaci\xf3 o altra addici\xf3 a la funcionalitat del Lloc quedar\xe0 subjecta a aquests Termes. Tots els avisos de copyright i altres avisos de propietat del Lloc s\u2019han de conservar en totes les c\xf2pies.","<strong><a target='_blank' href='/'>luiskr.com</a></strong> es reserva el dret de canviar, suspendre o cessar el Lloc amb o sense av\xeds. Acceptes que <strong><a target='_blank' href='/'>luiskr.com</a></strong> no ser\xe0 responsable davant teu ni de tercers per qualsevol canvi, interrupci\xf3 o cessament del Lloc o qualsevol part.","<strong>Sense suport ni manteniment.</strong> Acceptes que <strong><a target='_blank' href='/'>luiskr.com</a></strong> no t\xe9 cap obligaci\xf3 d\u2019oferir-te suport en relaci\xf3 amb el Lloc.","Excloent qualsevol contingut d\u2019usuari que puguis proporcionar, ets conscient que tots els drets de propietat intel\xb7lectual, incloent-hi drets d\u2019autor, patents, marques comercials i secrets comercials, del Lloc i el seu contingut, s\xf3n propietat de <strong><a target='_blank' href='/'>luiskr.com</a></strong> o dels prove\xefdors de <strong><a target='_blank' href='/'>luiskr.com</a></strong>. Aquests Termes i l\u2019acc\xe9s al Lloc no et concedeixen cap dret, t\xedtol o inter\xe8s sobre cap dret de propietat intel\xb7lectual, llevat dels drets d\u2019acc\xe9s limitats expressats a la Secci\xf3 2.1. <strong><a target='_blank' href='/'>luiskr.com</a></strong> i els seus prove\xefdors es reserven tots els drets no concedits en aquests Termes."],title:"Acc\xe9s al Lloc"},{content:["<strong>Enlla\xe7os de tercers.</strong> El Lloc pot contenir enlla\xe7os a llocs web i serveis de tercers. Aquests enlla\xe7os de tercers no estan sota el control de <strong><a target='_blank' href='/'>luiskr.com</a></strong>, i <strong><a target='_blank' href='/'>luiskr.com</a></strong> no n\u2019\xe9s responsable. <strong><a target='_blank' href='/'>luiskr.com</a></strong> proporciona acc\xe9s a aquests enlla\xe7os nom\xe9s per conveni\xe8ncia, i no els revisa, aprova, supervisa, avala ni garanteix, ni fa cap declaraci\xf3 sobre ells. Uses tots els enlla\xe7os de tercers sota el teu propi risc i has d\u2019aplicar un nivell adequat de precauci\xf3 i discreci\xf3. En fer clic en qualsevol enlla\xe7 de tercers, s\u2019apliquen els termes i pol\xedtiques del tercer corresponent, incloent-hi les seves pr\xe0ctiques de privacitat i recollida de dades.","<strong>Altres usuaris.</strong> Cada usuari del Lloc \xe9s l\u2019\xfanic responsable de tot el seu contingut d\u2019usuari. Com que no controlem el contingut d\u2019usuari, reconeixes i acceptes que no som responsables de cap contingut d\u2019usuari, proporcionat per tu o per altres. Acceptes que <strong><a target='_blank' href='/'>luiskr.com</a></strong> no ser\xe0 responsable de cap p\xe8rdua o dany derivat d\u2019aquestes interaccions. Si hi ha una disputa entre tu i qualsevol usuari del Lloc, no tenim cap obligaci\xf3 d\u2019intervenir.","Per la present, eximes i alliberes per sempre <strong><a target='_blank' href='/'>luiskr.com</a></strong> i els nostres directius, empleats, agents, successors i cessionaris de, i renuncies a, tota disputa, reclamaci\xf3, controv\xe8rsia, demanda, dret, obligaci\xf3, responsabilitat, acci\xf3 i causa d\u2019acci\xf3 de qualsevol tipus i naturalesa, passada, present o futura, que hagi sorgit o sorgeixi directa o indirectament del Lloc, o que hi estigui relacionada. Si ets resident de Calif\xf2rnia, renuncies a la secci\xf3 1542 del Codi Civil de Calif\xf2rnia en relaci\xf3 amb l\u2019anterior, que estableix: 'a general release does not extend to claims which the creditor does not know or suspect to exist in his or her favor at the time of executing the release, which if known by him or her must have materially affected his or her settlement with the debtor.'","<strong>Cookies i web beacons.</strong> Com qualsevol altre lloc web, <a target='_blank' href='/'>luiskr.com</a> usa 'cookies'. El consentiment per usar cookies es demana en accedir al lloc web i, si s\u2019accepta, aquestes cookies s\u2019usen per emmagatzemar informaci\xf3 com les prefer\xe8ncies dels visitants i les p\xe0gines visitades. La informaci\xf3 s\u2019usa per optimitzar l\u2019experi\xe8ncia dels usuaris personalitzant el contingut de la p\xe0gina segons el tipus de navegador i/o altra informaci\xf3."],title:"Enlla\xe7os de tercers; Altres usuaris"},{content:["El lloc es proporciona 'tal qual' i 'segons disponibilitat', i <strong><a target='_blank' href='/'>luiskr.com</a></strong> i els nostres prove\xefdors rebutgem expressament totes les garanties i condicions de qualsevol tipus, expresses, impl\xedcites o legals, incloent-hi totes les garanties de comerciabilitat, idone\xeftat per a un prop\xf2sit particular, t\xedtol, gaudi pac\xedfic, precisi\xf3 o no infracci\xf3. Nosaltres i els nostres prove\xefdors no garantim que el lloc compleixi els teus requisits, estigui disponible de manera ininterrompuda, puntual, segura o lliure d\u2019errors, ni que sigui prec\xeds, fiable, lliure de virus o altres codis nocius, complet, legal o segur. Si la llei aplicable requereix garanties relatives al lloc, totes aquestes garanties es limiten en durada a noranta (90) dies des de la data del primer \xfas.","Algunes jurisdiccions no permeten l\u2019exclusi\xf3 de garanties impl\xedcites, de manera que l\u2019exclusi\xf3 anterior pot no aplicar-se al teu cas. Algunes jurisdiccions no permeten limitacions sobre la durada d\u2019una garantia impl\xedcita, de manera que la limitaci\xf3 anterior pot no aplicar-se al teu cas."],title:"Exempcions de responsabilitat"},{content:["Fins al m\xe0xim perm\xe8s per la llei, en cap cas <strong><a target='_blank' href='/'>luiskr.com</a></strong> ni els nostres prove\xefdors seran responsables davant teu ni de tercers per lucre cessant, p\xe8rdua de dades, costos d\u2019adquisici\xf3 de productes substitutius, o danys indirectes, conseq\xfcents, exemplars, incidentals, especials o punitius derivats de aquests termes o del teu \xfas, o incapacitat d\u2019\xfas, del lloc, encara que <strong><a target='_blank' href='/'>luiskr.com</a></strong> hagi estat informat de la possibilitat d\u2019aquests danys. L\u2019acc\xe9s i l\u2019\xfas del lloc s\xf3n a la teva discreci\xf3 i risc, i ser\xe0s l\u2019\xfanic responsable de qualsevol dany al teu dispositiu o sistema inform\xe0tic, o de la p\xe8rdua de dades que en resulti.","Fins al m\xe0xim perm\xe8s per la llei, no obstant qualsevol disposici\xf3 en contrari, la nostra responsabilitat davant teu per qualsevol dany derivat d\u2019aquest acord o relacionat amb ell estar\xe0 en tot moment limitada a un m\xe0xim de cinquanta d\xf2lars estatunidencs (US $50). L\u2019exist\xe8ncia de m\xe9s d\u2019una reclamaci\xf3 no ampliar\xe0 aquest l\xedmit. Acceptes que els nostres prove\xefdors no tindran cap responsabilitat de cap tipus derivada d\u2019aquest acord o relacionada amb ell.","Algunes jurisdiccions no permeten la limitaci\xf3 o exclusi\xf3 de responsabilitat per danys incidentals o conseq\xfcents, de manera que la limitaci\xf3 o exclusi\xf3 anterior pot no aplicar-se al teu cas.","<strong>Vig\xe8ncia i cessament.</strong> Subjecte a aquesta Secci\xf3, aquests Termes romandran en ple vigor mentre usis el Lloc. Podem suspendre o cessar els teus drets d\u2019\xfas del Lloc en qualsevol moment i per qualsevol ra\xf3 a la nostra exclusiva discreci\xf3, incloent-hi qualsevol \xfas del Lloc en violaci\xf3 d\u2019aquests Termes. En cessar els teus drets sota aquests Termes, el teu Compte i el dret d\u2019acc\xe9s i \xfas del Lloc cessaran immediatament. Entens que el cessament del teu Compte pot implicar l\u2019esborrat del teu contingut d\u2019usuari associat al Compte de les nostres bases de dades actives. <strong><a target='_blank' href='/'>luiskr.com</a></strong> no tindr\xe0 cap responsabilitat davant teu per cap cessament dels teus drets sota aquests Termes. Fins i tot despr\xe9s del cessament dels teus drets, les disposicions seg\xfcents romandran en vigor: Seccions 2 a 2.5, Secci\xf3 3 i Seccions 4 a 10."],title:"Limitaci\xf3 de responsabilitat"},{content:["<strong><a target='_blank' href='/'>luiskr.com</a></strong> respecta la propietat intel\xb7lectual dels altres i demana que els usuaris del nostre Lloc facin el mateix. En relaci\xf3 amb el nostre Lloc, hem adoptat i implementat una pol\xedtica de respecte a la llei de drets d\u2019autor que preveu l\u2019eliminaci\xf3 de materials infringidors i el cessament d\u2019usuaris del nostre Lloc en l\xednia que infringueixin repetidament drets de propietat intel\xb7lectual, incloent-hi drets d\u2019autor. Si creus que un dels nostres usuaris, mitjan\xe7ant l\u2019\xfas del nostre Lloc, infringeix il\xb7legalment els drets d\u2019autor d\u2019una obra, i vols que el material presumptament infractor sigui eliminat, s\u2019ha de proporcionar la informaci\xf3 seg\xfcent en forma de notificaci\xf3 escrita (d\u2019acord amb 17 U.S.C. \xa7 512(c)) al nostre agent de drets d\u2019autor designat.<ul><li>la teva signatura f\xedsica o electr\xf2nica;</li><li>identificaci\xf3 de l\u2019obra o obres amb drets d\u2019autor que afirmes que han estat infringides;</li><li>identificaci\xf3 del material dels nostres serveis que afirmes que \xe9s infractor i que demanes que eliminem;</li><li>informaci\xf3 suficient per permetre\u2019ns localitzar aquest material;</li><li>la teva adre\xe7a, n\xfamero de tel\xe8fon i adre\xe7a de correu electr\xf2nic;</li><li>una declaraci\xf3 que creus de bona fe que l\u2019\xfas del material q\xfcestionat no est\xe0 autoritzat pel titular dels drets d\u2019autor, el seu agent o la llei; i</li><li>una declaraci\xf3 que la informaci\xf3 de la notificaci\xf3 \xe9s exacta i, sota pena de perjuri, que ets el titular dels drets d\u2019autor presumptament infringits o que est\xe0s autoritzat a actuar en nom del titular.</li></ul>","Tingues en compte que, d\u2019acord amb 17 U.S.C. \xa7 512(f), qualsevol declaraci\xf3 falsa de fets materials en una notificaci\xf3 escrita sotmet autom\xe0ticament la part reclamant a responsabilitat per danys, costos i honoraris d\u2019advocats en qu\xe8 incorreguem en relaci\xf3 amb la notificaci\xf3 escrita i l\u2019al\xb7legaci\xf3 d\u2019infracci\xf3 de drets d\u2019autor."],title:"Pol\xedtica de drets d\u2019autor."},{content:["Aquests Termes estan subjectes a revisi\xf3 ocasional; si fem canvis substancials, podem notificar-te enviant un correu electr\xf2nic a l\u2019\xfaltima adre\xe7a que ens vas proporcionar i/o publicant un av\xeds destacat dels canvis al Lloc. Ets responsable de proporcionar-nos la teva adre\xe7a de correu m\xe9s actualitzada. Si l\u2019\xfaltima adre\xe7a proporcionada no \xe9s v\xe0lida, l\u2019enviament del correu amb l\u2019av\xeds constituir\xe0 igualment una notificaci\xf3 efectiva dels canvis descrits. Qualsevol canvi en aquests Termes ser\xe0 efectiu el m\xe9s primerenc dels seg\xfcents: trenta (30) dies naturals despr\xe9s de l\u2019enviament del correu de notificaci\xf3, o trenta (30) dies naturals despr\xe9s de la publicaci\xf3 de l\u2019av\xeds de canvis al Lloc. Per a nous usuaris, els canvis seran efectius immediatament. L\u2019\xfas continuat del Lloc despr\xe9s de l\u2019av\xeds d\u2019aquests canvis indicar\xe0 el teu reconeixement dels canvis i el teu acord a quedar vinculat pels termes i condicions modificats. Resoluci\xf3 de disputes. Llegeix atentament aquest Acord d\u2019arbitratge. Forma part del teu contracte amb <strong><a target='_blank' href='/'>luiskr.com</a></strong> i afecta els teus drets. Cont\xe9 procediments d\u2019ARBITRATGE VINCULANT OBLIGATORI I REN\xdaNCIA A ACCIONS COL\xb7LECTIVES.","<strong>Aplicabilitat de l\u2019Acord d\u2019arbitratge.</strong> Totes les reclamacions i disputes en relaci\xf3 amb els Termes o l\u2019\xfas de qualsevol producte o servei proporcionat per <strong><a target='_blank' href='/'>luiskr.com</a></strong> que no es puguin resoldre informalment o en un tribunal de reclamacions menors es resoldran per arbitratge vinculant sobre base individual sota els termes d\u2019aquest Acord d\u2019arbitratge. Llevat que s\u2019acordi el contrari, tots els procediments d\u2019arbitratge es faran en angl\xe8s. Aquest Acord s\u2019aplica a tu i a <strong><a target='_blank' href='/'>luiskr.com</a></strong>, i a qualsevol subsidi\xe0ria, afiliada, agent, empleat, predecessor d\u2019inter\xe8s, successor i cessionari, aix\xed com a tots els usuaris o beneficiaris autoritzats o no autoritzats de serveis o b\xe9ns proporcionats sota els Termes.","<strong>Requisit de notificaci\xf3 i resoluci\xf3 informal de disputes.</strong> Abans que qualsevol de les parts pugui sol\xb7licitar arbitratge, la part ha d\u2019enviar primer a l\u2019altra una Notificaci\xf3 de disputa escrita descrivint la naturalesa i el fonament de la reclamaci\xf3 o disputa, i la reparaci\xf3 sol\xb7licitada. Una notificaci\xf3 a <strong><a target='_blank' href='/'>luiskr.com</a></strong> s\u2019ha d\u2019enviar a: Rua Hugo Costa Duarte, 32, APTO. 01, Caraj\xe1, Santana do Livramento (RS), BR. Despr\xe9s de rebre la notificaci\xf3, tu i <strong><a target='_blank' href='/'>luiskr.com</a></strong> podeu intentar resoldre la reclamaci\xf3 o disputa informalment. Si tu i <strong><a target='_blank' href='/'>luiskr.com</a></strong> no la resoleu en un termini de trenta (30) dies despr\xe9s de rebre la notificaci\xf3, qualsevol de les parts pot iniciar un procediment d\u2019arbitratge. L\u2019import de qualsevol oferta d\u2019acord feta per qualsevol part no es podr\xe0 revelar a l\u2019\xe0rbitre fins que aquest hagi determinat l\u2019import del laude al qual tingui dret cada part.","<strong>Regles d\u2019arbitratge.</strong> L\u2019arbitratge s\u2019iniciar\xe0 a trav\xe9s de l\u2019American Arbitration Association, un prove\xefdor establert de resoluci\xf3 alternativa de disputes que ofereix arbitratge com es disposa en aquesta secci\xf3. Si l\u2019AAA no est\xe0 disponible per arbitrar, les parts acordaran seleccionar un prove\xefdor alternatiu d\u2019ADR. Les regles del prove\xefdor d\u2019ADR regiran tots els aspectes de l\u2019arbitratge, llevat que entrin en conflicte amb els Termes. Les Regles d\u2019arbitratge del consumidor de l\u2019AAA estan disponibles en l\xednia a adr.org o trucant a l\u2019AAA al 1-800-778-7879. L\u2019arbitratge ser\xe0 condu\xeft per un \xfanic \xe0rbitre neutral. Qualsevol reclamaci\xf3 o disputa on l\u2019import total sol\xb7licitat sigui inferior a deu mil d\xf2lars estatunidencs (US $10.000,00) podr\xe0 resoldre\u2019s per arbitratge vinculant sense compareixen\xe7a, a opci\xf3 de la part que sol\xb7licita la reparaci\xf3. Per a reclamacions o disputes on l\u2019import total sol\xb7licitat sigui deu mil d\xf2lars estatunidencs (US $10.000,00) o m\xe9s, el dret a una vista ser\xe0 determinat per les regles d\u2019arbitratge. Qualsevol vista es far\xe0 en un lloc a menys de 160 km de la teva resid\xe8ncia, llevat que resideixis fora dels Estats Units i llevat que les parts acordin el contrari. Si resideixes fora dels EUA, l\u2019\xe0rbitre donar\xe0 a les parts un av\xeds raonable de la data, hora i lloc de qualsevol vista oral. Qualsevol sent\xe8ncia sobre el laude dictat per l\u2019\xe0rbitre podr\xe0 inscriure\u2019s en qualsevol tribunal de jurisdicci\xf3 competent. Cada part suportar\xe0 els seus propis costos i despeses derivats de l\u2019arbitratge i pagar\xe0 una part igual dels honoraris i costos del prove\xefdor d\u2019ADR.","<strong>Regles addicionals per a arbitratge sense compareixen\xe7a.</strong> Si s\u2019elegeix arbitratge sense compareixen\xe7a, l\u2019arbitratge es dur\xe0 a terme per tel\xe8fon, en l\xednia i/o basat \xfanicament en presentacions escrites; la manera espec\xedfica ser\xe0 triada per la part que inicia l\u2019arbitratge. L\u2019arbitratge no implicar\xe0 cap compareixen\xe7a personal de les parts ni dels testimonis, llevat que les parts ho acordin.","<strong>Terminis.</strong> Si tu o <strong><a target='_blank' href='/'>luiskr.com</a></strong> perseguiu arbitratge, l\u2019acci\xf3 d\u2019arbitratge s\u2019ha d\u2019iniciar i/o demanar dins el termini de prescripci\xf3 i dins qualsevol termini imposat per les regles de l\u2019AAA per a la reclamaci\xf3 pertinent.","<strong>Autoritat de l\u2019\xe0rbitre.</strong> Si s\u2019inicia arbitratge, l\u2019\xe0rbitre decidir\xe0 els drets i responsabilitats de tu i de <strong><a target='_blank' href='/'>luiskr.com</a></strong>, i la disputa no es consolidar\xe0 amb altres assumptes ni s\u2019ajuntar\xe0 amb altres casos o parts. L\u2019\xe0rbitre tindr\xe0 autoritat per concedir mocions que resolguin totalment o parcialment qualsevol reclamaci\xf3, atorgar danys monetaris i concedir qualsevol remei o reparaci\xf3 no monet\xe0ria disponible per a un individu sota la llei aplicable, les regles de l\u2019AAA i els Termes. L\u2019\xe0rbitre emetr\xe0 un laude escrit i una declaraci\xf3 de decisi\xf3 descrivint les constatacions i conclusions essencials en qu\xe8 es basa el laude. L\u2019\xe0rbitre t\xe9 la mateixa autoritat per concedir reparacions sobre base individual que tindria un jutge en un tribunal. El laude de l\u2019\xe0rbitre \xe9s final i vinculant per a tu i per a <strong><a target='_blank' href='/'>luiskr.com</a></strong>.","<strong>Ren\xfancia a judici amb jurat.</strong> LES PARTS RENUNCIEN ALS SEUS DRETS CONSTITUCIONALS I LEGALS D\u2019ANAR A UN TRIBUNAL I TENIR UN JUDICI DAVANT UN JUTGE O UN JURAT, elegint en canvi que totes les reclamacions i disputes es resolguin per arbitratge sota aquest Acord d\u2019arbitratge. Els procediments d\u2019arbitratge s\xf3n t\xedpicament m\xe9s limitats, m\xe9s eficients i menys costosos que les regles aplicables en un tribunal i estan subjectes a revisi\xf3 molt limitada per un tribunal. En cas que sorgeixi qualsevol litigi entre tu i <strong><a target='_blank' href='/'>luiskr.com</a></strong> en qualsevol tribunal estatal o federal per anul\xb7lar o executar un laude arbitral o altres, TU I <strong><a target='_blank' href='/'>luiskr.com</a></strong> RENUNCIEU A TOTS ELS DRETS A UN JUDICI AMB JURAT, elegint que la disputa sigui resolta per un jutge.","<strong>Ren\xfancia a accions col\xb7lectives o consolidades.</strong> Totes les reclamacions i disputes dins l\u2019abast d\u2019aquest acord d\u2019arbitratge s\u2019han d\u2019arbitrar o litigar sobre base individual i no sobre base col\xb7lectiva, i les reclamacions de m\xe9s d\u2019un client o usuari no es poden arbitrar o litigar conjuntament ni consolidar amb les de qualsevol altre client o usuari.","<strong>Confidencialitat.</strong> Tots els aspectes del procediment d\u2019arbitratge seran estrictament confidencials. Les parts acorden mantenir la confidencialitat llevat que la llei exigeixi el contrari. Aquest par\xe0graf no impedir\xe0 que una part presenti a un tribunal qualsevol informaci\xf3 necess\xe0ria per executar aquest Acord, executar un laude arbitral o sol\xb7licitar mesures cautelars o equitatives.","<strong>Divisibilitat.</strong> Si qualsevol part o parts d\u2019aquest Acord d\u2019arbitratge s\xf3n declarades inv\xe0lides o inexecutables per un tribunal de jurisdicci\xf3 competent, aquesta part o parts quedaran sense for\xe7a ni efecte i es separaran, i la resta de l\u2019Acord continuar\xe0 en ple vigor.","<strong>Dret de ren\xfancia.</strong> La part contra la qual s\u2019ha presentat la reclamaci\xf3 pot renunciar a qualsevol o tots els drets i limitacions establerts en aquest Acord d\u2019arbitratge. Aquesta ren\xfancia no renunciar\xe0 ni afectar\xe0 cap altra porci\xf3 d\u2019aquest Acord.","<strong>Superviv\xe8ncia de l\u2019Acord.</strong> Aquest Acord d\u2019arbitratge sobreviur\xe0 la terminaci\xf3 de la teva relaci\xf3 amb <strong><a target='_blank' href='/'>luiskr.com</a></strong>.","<strong>Tribunal de reclamacions menors.</strong> No obstant l\u2019anterior, tu o <strong><a target='_blank' href='/'>luiskr.com</a></strong> podeu presentar una acci\xf3 individual en un tribunal de reclamacions menors.","<strong>Reparaci\xf3 equitativa d\u2019emerg\xe8ncia.</strong> No obstant l\u2019anterior, qualsevol de les parts pot sol\xb7licitar una reparaci\xf3 equitativa d\u2019emerg\xe8ncia davant un tribunal estatal o federal per mantenir l\u2019statu quo pendent l\u2019arbitratge. Una sol\xb7licitud de mesures provisionals no es considerar\xe0 una ren\xfancia a altres drets o obligacions sota aquest Acord d\u2019arbitratge.","<strong>Reclamacions no subjectes a arbitratge.</strong> No obstant l\u2019anterior, les reclamacions de difamaci\xf3, violaci\xf3 del Computer Fraud and Abuse Act i infracci\xf3 o apropiaci\xf3 indeguda de patents, drets d\u2019autor, marques comercials o secrets comercials de l\u2019altra part no estaran subjectes a aquest Acord d\u2019arbitratge.","En qualsevol circumst\xe0ncia en qu\xe8 l\u2019Acord d\u2019arbitratge anterior permeti a les parts litigar en un tribunal, les parts acorden sotmetre\u2019s a la jurisdicci\xf3 personal dels tribunals ubicats a Netherlands County, Calif\xf2rnia, per a aquests efectes.","El Lloc pot estar subjecte a lleis de control d\u2019exportaci\xf3 dels EUA i a regulacions d\u2019exportaci\xf3 o importaci\xf3 d\u2019altres pa\xefsos. Acceptes no exportar, reexportar ni transferir, directa o indirectament, cap dada t\xe8cnica dels EUA adquirida de <strong><a target='_blank' href='/'>luiskr.com</a></strong>, ni cap producte que utilitzi aquestes dades, en violaci\xf3 de les lleis o regulacions d\u2019exportaci\xf3 dels Estats Units.","<strong><a target='_blank' href='/'>luiskr.com</a></strong> est\xe0 ubicat a l\u2019adre\xe7a de la Secci\xf3 10.8. Si ets resident de Calif\xf2rnia, pots presentar queixes a la Complaint Assistance Unit de la Division of Consumer Product del California Department of Consumer Affairs, per escrit a 400 R Street, Sacramento, CA 95814, o per tel\xe8fon al (800) 952-5210.","<strong>Comunicacions electr\xf2niques.</strong> Les comunicacions entre tu i <strong><a target='_blank' href='/'>luiskr.com</a></strong> usen mitjans electr\xf2nics, ja sigui que usis el Lloc o ens envi\xefs correus, o que <strong><a target='_blank' href='/'>luiskr.com</a></strong> publiqui avisos al Lloc o es comuniqui amb tu per correu. A efectes contractuals, (a) consents rebre comunicacions de <strong><a target='_blank' href='/'>luiskr.com</a></strong> en forma electr\xf2nica; i (b) acceptes que tots els termes i condicions, acords, avisos, revelacions i altres comunicacions que <strong><a target='_blank' href='/'>luiskr.com</a></strong> et proporciona electr\xf2nicament satisfan qualsevol obligaci\xf3 legal que aquestes comunicacions satisfarien si fossin per escrit en paper.","<strong>Termes complets.</strong> Aquests Termes constitueixen l\u2019acord complet entre tu i nosaltres pel que fa a l\u2019\xfas del Lloc. La nostra manca d\u2019exercici o compliment de qualsevol dret o disposici\xf3 d\u2019aquests Termes no operar\xe0 com a ren\xfancia a tal dret o disposici\xf3. Els t\xedtols de les seccions s\xf3n nom\xe9s per conveni\xe8ncia i no tenen efecte legal ni contractual. La paraula 'incloent' significa 'incloent sense limitaci\xf3'. Si qualsevol disposici\xf3 d\u2019aquests Termes es declara inv\xe0lida o inexecutable, les altres disposicions quedaran intactes i la disposici\xf3 inv\xe0lida o inexecutable es considerar\xe0 modificada perqu\xe8 sigui v\xe0lida i executable fins al m\xe0xim perm\xe8s per la llei. La teva relaci\xf3 amb <strong><a target='_blank' href='/'>luiskr.com</a></strong> \xe9s la d\u2019un contractista independent, i cap de les parts \xe9s agent o soci de l\u2019altra. Aquests Termes i els teus drets i obligacions no poden ser cedits, subcontractats, delegats ni transferits per tu sense el consentiment previ per escrit de <strong><a target='_blank' href='/'>luiskr.com</a></strong>; qualsevol intent de cessi\xf3, subcontracte, delegaci\xf3 o transfer\xe8ncia en violaci\xf3 d\u2019aix\xf2 ser\xe0 nul. <strong><a target='_blank' href='/'>luiskr.com</a></strong> pot cedir aquests Termes lliurement. Els termes i condicions establerts en aquests Termes seran vinculants per als cessionaris.","<strong>La teva privacitat.</strong> Llegeix la Pol\xedtica de privacitat.","<strong>Informaci\xf3 de drets d\u2019autor/marques.</strong> Copyright \xa9. Tots els drets reservats. Totes les marques comercials, logotips i marques de servei mostrades al Lloc s\xf3n propietat nostra o d\u2019altres tercers. No tens perm\xeds per usar aquestes Marques sense el nostre consentiment previ per escrit o el consentiment del tercer propietari de les Marques."],title:"General"},{content:["<a target='_blank' href='https://github.com/LuisKrotz/luiskr.com-V3' rel='noopener'>Qualsevol fork es pot fer via GitHub, sota llic\xe8ncia MIT, usant aquest enlla\xe7.</a>","<a target='_blank' href='https://github.com/LuisKrotz/luiskr.com-V2' rel='noopener'>Qualsevol fork de la versi\xf3 anterior del meu lloc web es pot fer usant aquest enlla\xe7.</a>"],title:"Repositori"},{content:["Correu:<a target='_blank' href='mailto:luis.krotz@gmail.com'>luis.krotz@gmail.com</a>","Tel\xe8fon:<a target='_blank' href='tel:+55(51) 982-274-782'>+55 51 982-274-782</a>"],title:"Informaci\xf3 de contacte"}],title:"Termes d\u2019\xfas"},"not-found":{title:"\ud83d\udc7d, \ud83d\udc7e, \ud83d\udc79, \ud83e\udd21, \ud83d\udc7b || \ud83e\udd16.<br>Tots ens perdem de vegades.",link:"Torna a la p\xe0gina principal."},"star-field":{title:"Camp Estel\xb7lar",instructions:"Instruccions",systemBoot:"Arrencada del Sistema",hint:"Arrossega per explorar \xb7 Rodeta per ampliar \xb7 Selecciona un cos per la seva hist\xf2ria",explore:"Carta Celeste",solar:"Sistema Solar",milkyWay:"Via L\xe0ctea",nebulae:"Nebuloses",galaxies:"Gal\xe0xies",satellite:"Sat\xe8l\xb7lit",screenshot:"Fes Captura",overview:"Vista General",loading:"Carregant\u2026",source:"Font",star:"Estrella",planet:"Planeta",dwarfPlanet:"Planeta Nan",asteroid:"Asteroide",comet:"Cometa",moon:"Lluna",blackHole:"Forat Negre",system:"Sistema Estel\xb7lar",nebula:"Nebulosa",galaxy:"Gal\xe0xia",cluster:"C\xfamul",acquired:"Dades adquirides",translated:"Tradu\xeft",search:"Cerca al cat\xe0leg\u2026",exoplanet:"Exoplaneta",dso:"Objecte de cel profund",catalog:"Cat\xe0leg profund",records:"registres",loadMore:"Carrega\u2019n m\xe9s",searching:"Cercant al cat\xe0leg\u2026",magnitude:"Magnitud aparent",distance:"Dist\xe0ncia",spectralType:"Tipus espectral",constellation:"Constel\xb7laci\xf3",designation:"Designaci\xf3",hostStar:"Estrella amfitriona",dsoType:"Tipus d\u2019objecte",discovery:"Descobriment",redshift:"Despla\xe7ament cap al vermell",coordinates:"Posici\xf3 helioc\xe8ntrica",registry_star:"Estrella catalogada",registry_star_about:"Una estrella real del cat\xe0leg HYG (Hipparcos/Gliese/Tycho): posici\xf3, magnitud i classe espectral de l\u2019astrometria publicada.",registry_exoplanet:"Exoplaneta confirmat",registry_exoplanet_about:"Un planeta confirmat del NASA Exoplanet Archive, mostrat a la posici\xf3 mesurada de la seva estrella amfitriona.",registry_dso:"Objecte de cel profund catalogat",registry_dso_about:"Un objecte NGC/IC del cat\xe0leg OpenNGC: gal\xe0xia, c\xfamul o nebulosa; dist\xe0ncia per despla\xe7ament cap al vermell quan est\xe0 disponible.",localGroup:"Grup Local",hierarchy:"Jerarquia C\xf2smica",dwarfGalaxy:"Gal\xe0xia Nana",structure:"Estructura C\xf2smica",belt:"Cintur\xf3",disclaimer:"Aquest experiment no simula dist\xe0ncies espacials reals ni l\u2019aparen\xe7a ni les formes reals dels objectes. La disposici\xf3 est\xe0 pensada per navegar i presentar la informaci\xf3 de forma interactiva \u2014 no reflecteix dades reals.",description:"Camp d'estrelles WebGL interactiu \u2014 vola pel Sistema Solar, estrelles properes, nebuloses i gal\xe0xies."},"earth-playground":{title:"Playground de la Terra",experienceSettings:"Configuraci\xf3 de l\u2019experi\xe8ncia",systemBoot:"Arrencada del sistema",camera:"C\xe0mera",fov:"FOV",rotateSpeed:"Velocitat de rotaci\xf3",autoRotate:"Autorotaci\xf3",resetView:"Restableix la vista",earth:"Terra",spinSpeed:"Velocitat de gir",engine:"Configuraci\xf3 del motor",waterMetalness:"Metal\xb7licitat de l\u2019aigua",terrain:"Configuraci\xf3 del terreny",bumpScale:"Escala del mapa de relleu",selfShadow:"Intensitat d\u2019ombra pr\xf2pia",selfShadowOff:"Despla\xe7ament d\u2019ombra pr\xf2pia",postFx:"Postprocessament",bloom:"Bloom",bloomStr:"For\xe7a del bloom",bloomRadius:"Radi del bloom",bloomThreshold:"Lindar del bloom",vignette:"Vinyeta",vigDarkness:"Foscor",vigOffset:"Despla\xe7ament",chromaticAb:"Aberraci\xf3 crom\xe0tica",caStrength:"For\xe7a CA",filmGrain:"Gra de pel\xb7l\xedcula",color:"Color",contrast:"Contrast",saturation:"Saturaci\xf3",blackLevel:"Nivell de negre",sunAutoRotate:"Autorotaci\xf3 del sol",displayDebug:"Visualitzaci\xf3 i depuraci\xf3",showStats:"Mostra estad\xedstiques",resScale:"Escala de resoluci\xf3",screenshot:"Fes una captura de pantalla",copyConstants:"Copia les constants de la GUI",position:"Posici\xf3 (actual)",target:"Objectiu (actual)",defaults:{waterMetalness:0,bumpScale:5,selfShadow:1,selfShadowOff:.002,bloom:!1,bloomStr:.1,bloomRadius:.3,bloomThreshold:.9,vignette:!1,vigDarkness:1,vigOffset:.5,chromaticAb:!1,caStrength:.25,filmGrain:0,fov:45,autoRotate:!1,rotateSpeed:.05,spinSpeed:1,sunAutoRotate:!0,contrast:1,saturation:1.5,blackLevel:.015,resScale:1},description:"Playground WebGL interactiu de la Terra \u2014 ajusta terreny, atmosfera, il\xb7luminaci\xf3 i postprocessat en directe."},license:{title:"Llic\xe8ncia P\xfablica Mozilla 2.0",sections:[{title:"Quant a aquest document",content:["Aquesta p\xe0gina cont\xe9 el text complet i oficial de la Mozilla Public License 2.0 (MPL 2.0), la llic\xe8ncia sota la qual es publica el codi font d'aquest lloc web. La llic\xe8ncia \xe9s una concessi\xf3 mundial, lliure de royalties, v\xe0lida a tots els pa\xefsos i territoris.","El text en angl\xe8s \xe9s la versi\xf3 legal oficial. Les traduccions d'aquesta p\xe0gina a altres idiomes es proporcionen nom\xe9s per conveni\xe8ncia; si una traducci\xf3 difereix de l'original angl\xe8s, preval el text en angl\xe8s."]},{title:"1. Definicions",content:["1.1. &quot;Contribu\xefdor&quot; significa cada persona f\xedsica o jur\xeddica que crea, contribueix a la creaci\xf3 o \xe9s propiet\xe0ria de Programari Cobert.","1.2. &quot;Versi\xf3 del Contribu\xefdor&quot; significa la combinaci\xf3 de les Contribucions de tercers (si n'hi ha) utilitzades per un Contribu\xefdor i la Contribuci\xf3 d'aquest Contribu\xefdor en particular.","1.3. &quot;Contribuci\xf3&quot; significa el Programari Cobert d'un Contribu\xefdor concret.","1.4. &quot;Programari Cobert&quot; significa la Forma de Codi Font a la qual el Contribu\xefdor inicial ha adjuntat l'av\xeds de l'Annex A, la Forma Executable d'aquesta Forma de Codi Font i les Modificacions d'aquesta Forma de Codi Font, incloent-hi en cada cas parts de la mateixa.","1.5. &quot;Incompatible amb Llic\xe8ncies Secund\xe0ries&quot; significa (a) que el Contribu\xefdor inicial ha adjuntat al Programari Cobert l'av\xeds descrit a l'Annex B; o (b) que el Programari Cobert s'ha posat a disposici\xf3 sota els termes de la versi\xf3 1.1 o anterior de la Llic\xe8ncia, per\xf2 no tamb\xe9 sota els termes d'una Llic\xe8ncia Secund\xe0ria.","1.6. &quot;Forma Executable&quot; significa qualsevol forma de l'obra diferent de la Forma de Codi Font.","1.7. &quot;Obra Major&quot; significa una obra que combina Programari Cobert amb altre material, en un o diversos fitxers separats, que no \xe9s Programari Cobert.","1.8. &quot;Llic\xe8ncia&quot; significa aquest document.","1.9. &quot;Llicenciable&quot; significa tenir el dret de concedir, en la m\xe0xima mesura possible, ja sigui en el moment de la concessi\xf3 inicial o posteriorment, tots i cadascun dels drets atorgats per aquesta Llic\xe8ncia.","1.10. &quot;Modificacions&quot; significa qualsevol dels seg\xfcents: (a) qualsevol fitxer en Forma de Codi Font que resulti d'una addici\xf3, supressi\xf3 o modificaci\xf3 del contingut del Programari Cobert; o (b) qualsevol fitxer nou en Forma de Codi Font que contingui Programari Cobert.","1.11. Les &quot;Reivindicacions de Patent&quot; d'un Contribu\xefdor significa qualsevol reivindicaci\xf3 de patent, incloent-hi, entre d'altres, les reivindicacions de m\xe8tode, proc\xe9s i aparell, de qualsevol patent Llicenciable per aquest Contribu\xefdor que seria infringida, si no fos per la concessi\xf3 de la Llic\xe8ncia, per la fabricaci\xf3, l'\xfas, la venda, l'oferta de venda, l'enc\xe0rrec de fabricaci\xf3, la importaci\xf3 o la transfer\xe8ncia de les seves Contribucions o de la seva Versi\xf3 del Contribu\xefdor.","1.12. &quot;Llic\xe8ncia Secund\xe0ria&quot; significa la GNU General Public License, Versi\xf3 2.0, la GNU Lesser General Public License, Versi\xf3 2.1, la GNU Affero General Public License, Versi\xf3 3.0, o qualsevol versi\xf3 posterior d'aquestes llic\xe8ncies.","1.13. &quot;Forma de Codi Font&quot; significa la forma de l'obra preferida per fer modificacions.","1.14. &quot;V\xf3s&quot; (o &quot;Vostre&quot;) significa una persona f\xedsica o jur\xeddica que exerceix drets en virtut d'aquesta Llic\xe8ncia. Per a les persones jur\xeddiques, &quot;V\xf3s&quot; inclou qualsevol entitat que controla, \xe9s controlada o est\xe0 sota control com\xfa amb V\xf3s. Als efectes d'aquesta definici\xf3, &quot;control&quot; significa (a) el poder, directe o indirecte, de dirigir la gesti\xf3 d'aquesta entitat, ja sigui per contracte o d'una altra manera, o (b) la propietat de m\xe9s del cinquanta per cent (50%) de les participacions en circulaci\xf3 o la titularitat beneficiosa d'aquesta entitat."]},{title:"2. Concessions i condicions de la Llic\xe8ncia",content:["2.1. Concessions \u2014 Cada Contribu\xefdor us concedeix per la present una llic\xe8ncia mundial, lliure de royalties i no exclusiva: (a) en virtut dels drets de propietat intel\xb7lectual (diferents de patents o marques) Llicenciables per aquest Contribu\xefdor per usar, reproduir, posar a disposici\xf3, modificar, exhibir, executar, distribuir i explotar d'una altra manera les seves Contribucions, ja sigui sense modificar, amb Modificacions o com a part d'una Obra Major; i (b) en virtut de les Reivindicacions de Patent d'aquest Contribu\xefdor per fabricar, usar, vendre, oferir en venda, encarregar la fabricaci\xf3, importar i transferir d'una altra manera les seves Contribucions o la seva Versi\xf3 del Contribu\xefdor.","2.2. Data d'entrada en vigor \u2014 Les llic\xe8ncies concedides a la Secci\xf3 2.1 respecte a qualsevol Contribuci\xf3 entren en vigor per a cada Contribuci\xf3 a la data en qu\xe8 el Contribu\xefdor la distribueix per primera vegada.","2.3. Limitacions de l'abast de la concessi\xf3 \u2014 Les llic\xe8ncies concedides en aquesta Secci\xf3 2 s\xf3n els \xfanics drets concedits en virtut d'aquesta Llic\xe8ncia. No se'n derivar\xe0 cap dret ni llic\xe8ncia addicional de la distribuci\xf3 o concessi\xf3 de llic\xe8ncies del Programari Cobert en virtut d'aquesta Llic\xe8ncia. No obstant la Secci\xf3 2.1(b) anterior, cap Contribu\xefdor no concedeix llic\xe8ncia de patent: (a) per a cap codi que un Contribu\xefdor hagi eliminat del Programari Cobert; ni (b) per a infraccions causades per: (i) les modificacions vostres i de tercers del Programari Cobert, o (ii) la combinaci\xf3 de les seves Contribucions amb un altre programari (llevat com a part de la seva Versi\xf3 del Contribu\xefdor); ni (c) en virtut de Reivindicacions de Patent infringides pel Programari Cobert en abs\xe8ncia de les seves Contribucions. Aquesta Llic\xe8ncia no concedeix cap dret sobre marques comercials, marques de servei ni logotips de cap Contribu\xefdor (llevat en la mesura necess\xe0ria per complir els requisits d'av\xeds de la Secci\xf3 3.4).","2.4. Llic\xe8ncies posteriors \u2014 Cap Contribu\xefdor no fa concessions addicionals a conseq\xfc\xe8ncia de la vostra elecci\xf3 de distribuir el Programari Cobert sota una versi\xf3 posterior d'aquesta Llic\xe8ncia (vegeu la Secci\xf3 10.2) o sota els termes d'una Llic\xe8ncia Secund\xe0ria (si ho permeten els termes de la Secci\xf3 3.3).","2.5. Declaraci\xf3 \u2014 Cada Contribu\xefdor declara que creu que les seves Contribucions s\xf3n la seva o les seves creacions originals, o que disposa de drets suficients per concedir els drets sobre les seves Contribucions que atorga aquesta Llic\xe8ncia.","2.6. \xdas just \u2014 Aquesta Llic\xe8ncia no pret\xe9n limitar cap dret que tingueu en virtut de les doctrines d'\xfas just (fair use), tracte just (fair dealing) o altres equivalents del dret d'autor aplicables.","2.7. Condicions \u2014 Les Seccions 3.1, 3.2, 3.3 i 3.4 s\xf3n condicions de les llic\xe8ncies concedides a la Secci\xf3 2.1."]},{title:"3. Responsabilitats",content:["3.1. Distribuci\xf3 de la Forma de Codi Font \u2014 Tota distribuci\xf3 del Programari Cobert en Forma de Codi Font, incloent-hi les Modificacions que creeu o a les quals contribu\xefu, s'ha de fer sota els termes d'aquesta Llic\xe8ncia. Heu d'informar els destinataris que la Forma de Codi Font del Programari Cobert es regeix pels termes d'aquesta Llic\xe8ncia i de com poden obtenir una c\xf2pia d'aquesta Llic\xe8ncia. No podeu intentar alterar ni restringir els drets dels destinataris sobre la Forma de Codi Font.","3.2. Distribuci\xf3 de la Forma Executable \u2014 Si distribu\xefu el Programari Cobert en Forma Executable, llavors: (a) aquest Programari Cobert tamb\xe9 s'ha de posar a disposici\xf3 en Forma de Codi Font, tal com es descriu a la Secci\xf3 3.1, i heu d'informar els destinataris de la Forma Executable de com poden obtenir una c\xf2pia d'aquesta Forma de Codi Font per mitjans raonables i de manera oportuna, per un import no superior al cost de distribuci\xf3 al destinatari; i (b) podeu distribuir aquesta Forma Executable sota els termes d'aquesta Llic\xe8ncia, o sublicenciar-la sota termes diferents, sempre que la llic\xe8ncia de la Forma Executable no intenti limitar ni alterar els drets dels destinataris sobre la Forma de Codi Font en virtut d'aquesta Llic\xe8ncia.","3.3. Distribuci\xf3 d'una Obra Major \u2014 Podeu crear i distribuir una Obra Major sota els termes que trieu, sempre que tamb\xe9 compliu els requisits d'aquesta Llic\xe8ncia per al Programari Cobert. Si l'Obra Major \xe9s una combinaci\xf3 del Programari Cobert amb una obra regida per una o m\xe9s Llic\xe8ncies Secund\xe0ries, i el Programari Cobert no \xe9s Incompatible amb Llic\xe8ncies Secund\xe0ries, aquesta Llic\xe8ncia us permet distribuir addicionalment aquest Programari Cobert sota els termes d'aquesta(es) Llic\xe8ncia(es) Secund\xe0ria(es), de manera que el destinatari de l'Obra Major pugui, a la seva elecci\xf3, continuar distribuint el Programari Cobert sota els termes d'aquesta Llic\xe8ncia o d'aquesta(es) Llic\xe8ncia(es) Secund\xe0ria(es).","3.4. Avisos \u2014 No podeu eliminar ni alterar la subst\xe0ncia de cap av\xeds de llic\xe8ncia (incloent-hi avisos de drets d'autor, avisos de patent, exempcions de garantia o limitacions de responsabilitat) contingut a la Forma de Codi Font del Programari Cobert, llevat que podeu alterar els avisos de llic\xe8ncia en la mesura necess\xe0ria per corregir inexactituds f\xe0ctiques conegudes.","3.5. Aplicaci\xf3 de termes addicionals \u2014 Podeu optar per oferir, i cobrar una tarifa per, garantia, suport, indemnitzaci\xf3 o obligacions de responsabilitat a un o m\xe9s destinataris del Programari Cobert. Tanmateix, nom\xe9s ho podeu fer en nom vostre i no en nom de cap Contribu\xefdor. Heu de deixar absolutament clar que qualsevol garantia, suport, indemnitzaci\xf3 o obligaci\xf3 de responsabilitat l'oferiu \xfanicament v\xf3s, i accepteu indemnitzar cada Contribu\xefdor per qualsevol responsabilitat en qu\xe8 incorri aquest Contribu\xefdor a conseq\xfc\xe8ncia dels termes de garantia, suport, indemnitzaci\xf3 o responsabilitat que oferiu. Podeu incloure exempcions de garantia i limitacions de responsabilitat addicionals espec\xedfiques de qualsevol jurisdicci\xf3."]},{title:"4. Impossibilitat de compliment per llei o reglament",content:["Si us resulta impossible complir algun dels termes d'aquesta Llic\xe8ncia respecte a part o a la totalitat del Programari Cobert a causa d'una llei, una ordre judicial o un reglament, heu de: (a) complir els termes d'aquesta Llic\xe8ncia en la m\xe0xima mesura possible; i (b) descriure les limitacions i el codi al qual afecten. Aquesta descripci\xf3 s'ha d'incloure en un fitxer de text que acompanyi totes les distribucions del Programari Cobert en Forma de Codi Font. Llevat en la mesura en qu\xe8 ho prohibeixi la llei o el reglament, aquesta descripci\xf3 ha de ser prou detallada perqu\xe8 un destinatari d'habilitat ordin\xe0ria la pugui comprendre."]},{title:"5. Resoluci\xf3",content:["5.1. Els drets concedits en virtut d'aquesta Llic\xe8ncia s'extingeixen autom\xe0ticament si incompl\xedu qualsevol dels seus termes. Tanmateix, si torneu a complir-los, els drets concedits en virtut d'aquesta Llic\xe8ncia per un Contribu\xefdor concret es restableixen (a) provisionalment, llevat i fins que aquest Contribu\xefdor rescindeixi expressament i definitivament les vostres concessions, i (b) de forma continuada, si aquest Contribu\xefdor no us notifica l'incompliment per mitjans raonables abans que hagin transcorregut 60 dies des que vau tornar al compliment. A m\xe9s, les vostres concessions d'un Contribu\xefdor concret es restableixen de forma continuada si aquest Contribu\xefdor us notifica l'incompliment per mitjans raonables, si \xe9s la primera vegada que rebeu una notificaci\xf3 d'incompliment d'aquesta Llic\xe8ncia d'aquest Contribu\xefdor i si torneu al compliment abans que hagin transcorregut 30 dies des de la recepci\xf3 de la notificaci\xf3.","5.2. Si inicieu un litigi contra qualsevol entitat allegant una reclamaci\xf3 d'infracci\xf3 de patent (excloses les accions de judici declaratiu, les reconvencions i les demandes creuades) afirmant que una Versi\xf3 del Contribu\xefdor infringeix directament o indirectament qualsevol patent, els drets que us concedeixen tots els Contribu\xefdors per al Programari Cobert en virtut de la Secci\xf3 2.1 d'aquesta Llic\xe8ncia s'extingiran.","5.3. En cas de resoluci\xf3 en virtut de les Seccions 5.1 o 5.2 anteriors, tots els contractes de llic\xe8ncia d'usuari final (exclosos distribu\xefdors i revenedors) que h\xe0giu concedit v\xe0lidament v\xf3s o els vostres distribu\xefdors en virtut d'aquesta Llic\xe8ncia abans de la resoluci\xf3 sobreviuran a aquesta."]},{title:"6. Exempci\xf3 de garantia",content:["EL PROGRAMARI COBERT ES PROPORCIONA EN VIRTUT D'AQUESTA LLIC\xc8NCIA &quot;TAL QUAL&quot;, SENSE GARANTIA DE CAP TIPUS, JA SIGUI EXPRESSA, IMPL\xcdCITA O LEGAL, INCLOENT-HI, ENTRE D'ALTRES, LES GARANTIES QUE EL PROGRAMARI COBERT EST\xc0 LLIURE DE DEFECTES, \xc9S COMERCIALITZABLE, \xc9S APTE PER A UNA FINALITAT DETERMINADA O NO INFRINGEIX DRETS. TOT EL RISC RELATIU A LA QUALITAT I EL RENDIMENT DEL PROGRAMARI COBERT \xc9S VOSTRE. SI ALGUN PROGRAMARI COBERT RESULT\xc9S DEFECTU\xd3S EN QUALSEVOL ASPECTE, V\xd3S (I NO CAP CONTRIBU\xcfDOR) ASSUMIU EL COST DE QUALSEVOL MANTENIMENT, REPARACI\xd3 O CORRECCI\xd3 NECESS\xc0RIA. AQUESTA EXEMPCI\xd3 DE GARANTIA CONSTITUEIX UNA PART ESSENCIAL D'AQUESTA LLIC\xc8NCIA. CAP \xdaS DEL PROGRAMARI COBERT NO EST\xc0 AUTORITZAT EN VIRTUT D'AQUESTA LLIC\xc8NCIA EXCEPTE SOTA AQUESTA EXEMPCI\xd3."]},{title:"7. Limitaci\xf3 de responsabilitat",content:["EN CAP CIRCUMST\xc0NCIA I SOTA CAP TEORIA LEGAL, JA SIGUI PER RESPONSABILITAT EXTRACONTRACTUAL (INCLOENT-HI LA NEGLIG\xc8NCIA), PER CONTRACTE O D'UNA ALTRA MANERA, CAP CONTRIBU\xcfDOR NI NING\xda QUE DISTRIBUEIXI EL PROGRAMARI COBERT SEGONS EL PERM\xc8S ANTERIORMENT NO SER\xc0 RESPONSABLE DAVANT V\xd3S DE CAP DANY DIRECTE, INDIRECTE, ESPECIAL, INCIDENTAL O CONSEq\xfcENT DE QUALSEVOL TIPUS, INCLOENT-HI, ENTRE D'ALTRES, DANYS PER LUCRE CESSANT, P\xc8RDUA DE CLIENTELA, INTERRUPCI\xd3 DEL TREBALL, FALLADA O MAL FUNCIONAMENT INFORM\xc0TIC, O QUALSEVOL ALTRE DANY O P\xc8RDUA COMERCIAL, FINS I TOT SI AQUESTA PART HAGU\xc9S ESTAT INFORMADA DE LA POSSIBILITAT D'AQUESTS DANYS. AQUESTA LIMITACI\xd3 DE RESPONSABILITAT NO S'APLICAR\xc0 A LA RESPONSABILITAT PER MORT O LESIONS PERSONALS DERIVADES DE LA NEGLIG\xc8NCIA D'AQUESTA PART EN LA MESURA EN QU\xc8 LA LLEI APLICABLE PROHIBEIXI AQUESTA LIMITACI\xd3. ALGUNES JURISDICCIONS NO PERMETEN L'EXCLUSI\xd3 O LIMITACI\xd3 DE DANYS INCIDENTALS O CONSEq\xfcENTS, PER LA QUAL COSA \xc9S POSSIBLE QUE AQUESTA EXCLUSI\xd3 I LIMITACI\xd3 NO US SIGUIN APLICABLES."]},{title:"8. Litigis",content:["Qualsevol litigi relacionat amb aquesta Llic\xe8ncia nom\xe9s es podr\xe0 interposar davant els tribunals de la jurisdicci\xf3 on el demandat tingui el seu establiment principal, i aquest litigi es regir\xe0 per les lleis d'aquesta jurisdicci\xf3, sense refer\xe8ncia a les seves normes sobre conflicte de lleis. Res del que es disposa en aquesta Secci\xf3 impedir\xe0 la capacitat d'una part per interposar reconvencions o demandes creuades."]},{title:"9. Disposicions diverses",content:["Aquesta Llic\xe8ncia representa l'acord complet relatiu al seu objecte. Si alguna disposici\xf3 d'aquesta Llic\xe8ncia es considera inaplicable, aquesta disposici\xf3 es reformar\xe0 \xfanicament en la mesura necess\xe0ria per fer-la exigible. Cap llei o reglament que estableixi que la llengua d'un contracte s'ha d'interpretar en contra del redactor s'utilitzar\xe0 per interpretar aquesta Llic\xe8ncia en contra d'un Contribu\xefdor."]},{title:"10. Versions de la Llic\xe8ncia",content:["10.1. Noves versions \u2014 La Mozilla Foundation \xe9s l'administradora de la llic\xe8ncia. Llevat del que disposa la Secci\xf3 10.3, ning\xfa m\xe9s que l'administradora de la llic\xe8ncia t\xe9 dret a modificar o publicar noves versions d'aquesta Llic\xe8ncia. A cada versi\xf3 se li assignar\xe0 un n\xfamero de versi\xf3 distintiu.","10.2. Efecte de les noves versions \u2014 Podeu distribuir el Programari Cobert sota els termes de la versi\xf3 de la Llic\xe8ncia sota la qual vau rebre originalment el Programari Cobert, o sota els termes de qualsevol versi\xf3 posterior publicada per l'administradora de la llic\xe8ncia.","10.3. Versions modificades \u2014 Si creeu un programari no regit per aquesta Llic\xe8ncia i voleu crear una nova llic\xe8ncia per a aquest programari, podeu crear i usar una versi\xf3 modificada d'aquesta Llic\xe8ncia si reanomeneu la llic\xe8ncia i elimineu tota refer\xe8ncia al nom de l'administradora de la llic\xe8ncia (llevat per indicar que aquesta llic\xe8ncia modificada difereix d'aquesta Llic\xe8ncia).","10.4. Distribuci\xf3 de la Forma de Codi Font Incompatible amb Llic\xe8ncies Secund\xe0ries \u2014 Si decidiu distribuir una Forma de Codi Font Incompatible amb Llic\xe8ncies Secund\xe0ries sota els termes d'aquesta versi\xf3 de la Llic\xe8ncia, s'hi ha d'adjuntar l'av\xeds descrit a l'Annex B d'aquesta Llic\xe8ncia."]},{title:"Annex A \u2014 Av\xeds de llic\xe8ncia de la Forma de Codi Font",content:["Aquesta Forma de Codi Font est\xe0 subjecta als termes de la Mozilla Public License, v. 2.0. Si no es va distribuir una c\xf2pia de la MPL amb aquest fitxer, en podeu obtenir una a https://mozilla.org/MPL/2.0/.","Si no \xe9s possible ni convenient col\xb7locar l'av\xeds en un fitxer concret, podeu incloure l'av\xeds en un lloc (com ara un fitxer LICENSE en un directori rellevant) on un destinatari probablement el cercaria.","Podeu afegir avisos addicionals i exactes de titularitat de drets d'autor."]},{title:"Annex B \u2014 Av\xeds d'&quot;Incompatible amb Llic\xe8ncies Secund\xe0ries&quot;",content:["Aquesta Forma de Codi Font \xe9s &quot;Incompatible amb Llic\xe8ncies Secund\xe0ries&quot;, tal com la defineix la Mozilla Public License, v. 2.0."]}]},animations:{title:"Refer\xe8ncia d'Animacions",description:"Totes les animacions del lloc, descrites \u2014 element, moviment, activador, tecnologia i prop\xf2sit \u2014 per a lectors, tecnologies d'assist\xe8ncia i agents d'IA."}}}}))()}var a,i;import{n as r,t}from"./rolldown-runtime-CKc5dgUC.js";a=r({default:()=>i});export{e as n,a as t};